window.FLASHCARD_DATA=[{"id": "vap_d7be880e2186", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "ändern + an", "cat": "vp", "syn": ["verändern", "modifizieren", "anpassen", "umgestalten"], "ex": ["An dieser Situation kann man noch etwas ändern."], "_exampleTrans": {"en": "One can still change something about this situation.", "tr": "Bu durumda hâlâ değiştirilebilecek bir şey var.", "ru": "В этой ситуации ещё можно кое-что изменить.", "uk": "У цій ситуації ще можна дещо змінити.", "es": "Todavía se puede cambiar algo de esta situación.", "fa": "هنوز می‌توان در این وضعیت چیزی را تغییر داد.", "ar": "ما زال يمكن تغيير شيء ما في هذا الوضع."}}, {"id": "vap_d2add71bef6f", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "denken + an", "cat": "vp", "syn": ["überlegen", "meinen", "nachdenken", "reflektieren"], "ex": ["Ich denke oft an meine berufliche Zukunft."], "_exampleTrans": {"en": "I often think about my professional future.", "tr": "Sık sık mesleki geleceğimi düşünüyorum.", "ru": "Я часто думаю о своём профессиональном будущем.", "uk": "Я часто думаю про своє професійне майбутнє.", "es": "A menudo pienso en mi futuro profesional.", "fa": "من اغلب به آیندهٔ شغلی‌ام فکر می‌کنم.", "ar": "أفكر كثيرًا في مستقبلي المهني."}}, {"id": "vap_69036259918d", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich erinnern + an", "cat": "vp", "syn": ["sich entsinnen", "zurückdenken", "sich besinnen", "in Erinnerung rufen"], "ex": ["Franziska kann sich recht gut an das Projekt erinnern."], "_exampleTrans": {"en": "Franziska can remember the project quite well.", "tr": "Franziska projeyi oldukça iyi hatırlayabiliyor.", "ru": "Франциска может довольно хорошо вспомнить этот проект.", "uk": "Франциска може досить добре пригадати цей проєкт.", "es": "Franziska puede recordar bastante bien el proyecto.", "fa": "فرانتسیسکا می‌تواند آن پروژه را خیلی خوب به یاد بیاورد.", "ar": "تستطيع فرانزيسكا أن تتذكر المشروع جيدًا إلى حدّ كبير."}}, {"id": "vap_2a56ff0470ec", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich gewöhnen + an", "cat": "vp", "syn": ["sich anpassen", "sich einleben", "sich vertraut machen", "sich akklimatisieren"], "ex": ["Ich habe mich an das Essen gewöhnt."], "_exampleTrans": {"en": "I have got used to the food.", "tr": "Yemeğe alıştım.", "ru": "Я привык к еде.", "uk": "Я звик до їжі.", "es": "Me he acostumbrado a la comida.", "fa": "من به غذا عادت کرده‌ام.", "ar": "لقد اعتدتُ على الطعام."}}, {"id": "vap_5ac7e6b0792e", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "glauben + an", "cat": "vp", "syn": ["vertrauen", "überzeugt sein", "annehmen", "glauben"], "ex": ["Er glaubt an den Erfolg der Marketingmaßnahme."], "_exampleTrans": {"en": "He believes in the success of the marketing measure.", "tr": "Pazarlama önleminin başarısına inanıyor.", "ru": "Он верит в успех маркетингового мероприятия.", "uk": "Він вірить в успіх маркетингового заходу.", "es": "Él cree en el éxito de la medida de marketing.", "fa": "او به موفقیت اقدام بازاریابی باور دارد.", "ar": "إنه يؤمن بنجاح إجراء التسويق."}}, {"id": "vap_20bcff002fa6", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "es liegt + an", "cat": "vp", "syn": ["beruhen", "verursacht sein", "zurückzuführen sein", "abhängen"], "ex": ["Dass ich Kopfschmerzen habe, liegt am Wetter."], "_exampleTrans": {"en": "The fact that I have a headache is due to the weather.", "tr": "Başımın ağrımasının nedeni hava durumu.", "ru": "То, что у меня болит голова, связано с погодой.", "uk": "Те, що в мене болить голова, пов’язано з погодою.", "es": "El hecho de que tenga dolor de cabeza se debe al tiempo.", "fa": "این‌که سردرد دارم به خاطر آب‌وهواست.", "ar": "إن إصابتي بالصداع ترجع إلى الطقس."}}, {"id": "vap_d42ca5a52afc", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "richten + an", "cat": "vp", "syn": ["adressieren", "wenden", "ausrichten", "richten"], "ex": ["Sie richtete die Bitte an ihre Kollegen."], "_exampleTrans": {"en": "She addressed the request to her colleagues.", "tr": "Ricasını meslektaşlarına yöneltti.", "ru": "Она адресовала просьбу своим коллегам.", "uk": "Вона адресувала прохання своїм колегам.", "es": "Ella dirigió la petición a sus colegas.", "fa": "او درخواست را خطاب به همکارانش مطرح کرد.", "ar": "وجّهت الطلب إلى زملائها."}}, {"id": "vap_1c6d27012b27", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "teilnehmen + an", "cat": "vp", "syn": ["mitmachen", "sich beteiligen", "teilnehmen", "dabei sein"], "ex": ["Ich nehme an dem Projekt teil."], "_exampleTrans": {"en": "I am taking part in the project.", "tr": "Projeye katılıyorum.", "ru": "Я участвую в проекте.", "uk": "Я беру участь у проєкті.", "es": "Participo en el proyecto.", "fa": "من در پروژه شرکت می‌کنم.", "ar": "أنا أشارك في المشروع."}}, {"id": "vap_f6e3cf74012b", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich wenden + an", "cat": "vp", "syn": ["sich wenden", "kontaktieren", "ansprechen", "aufsuchen"], "ex": ["Er hat sich an den Betriebsrat gewendet."], "_exampleTrans": {"en": "He turned to the works council.", "tr": "O, işletme kuruluna başvurdu.", "ru": "Он обратился в производственный совет.", "uk": "Він звернувся до виробничої ради.", "es": "Él se dirigió al comité de empresa.", "fa": "او به شورای کارگاه مراجعه کرد.", "ar": "توجّه إلى مجلس العاملين."}}, {"id": "vap_977cbb9d4ebd", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "zweifeln + an", "cat": "vp", "syn": ["misstrauen", "bezweifeln", "zweifeln", "skeptisch sein"], "ex": ["Sie hat nie am Erfolg des Projekts gezweifelt."], "_exampleTrans": {"en": "She never doubted the success of the project.", "tr": "Projenin başarısından hiç şüphe duymadı.", "ru": "Она никогда не сомневалась в успехе проекта.", "uk": "Вона ніколи не сумнівалася в успіху проєкту.", "es": "Ella nunca dudó del éxito del proyecto.", "fa": "او هرگز در موفقیت پروژه تردید نکرد.", "ar": "لم تشكّ أبدًا في نجاح المشروع."}}, {"id": "vap_33ceacdeecb0", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "abwälzen + auf", "cat": "vp", "syn": ["übertragen", "abschieben", "aufbürden", "zuschieben"], "ex": ["Klaus wälzt die ganze Arbeit auf seinen Kollegen ab."], "_exampleTrans": {"en": "Klaus shifts all the work onto his colleague.", "tr": "Klaus bütün işi meslektaşının üzerine yıkıyor.", "ru": "Клаус перекладывает всю работу на своего коллегу.", "uk": "Клаус перекладає всю роботу на свого колегу.", "es": "Klaus descarga todo el trabajo en su colega.", "fa": "کلاوس تمام کار را به گردن همکارش می‌اندازد.", "ar": "يلقي كلاوس كل العمل على زميله."}}, {"id": "vap_020cd83ed53f", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "achten + auf", "cat": "vp", "syn": ["beachten", "berücksichtigen", "aufpassen", "Wert legen"], "ex": ["Sebastian achtet sehr auf sein Aussehen."], "_exampleTrans": {"en": "Sebastian pays a lot of attention to his appearance.", "tr": "Sebastian görünüşüne çok dikkat eder.", "ru": "Себастиан очень следит за своей внешностью.", "uk": "Себастіан дуже дбає про свій зовнішній вигляд.", "es": "Sebastian presta mucha atención a su aspecto.", "fa": "زباستیان خیلی به ظاهرش توجه می‌کند.", "ar": "يهتم سيباستيان كثيرًا بمظهره."}}, {"id": "vap_35d60e64502c", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "ankommen + auf", "cat": "vp", "syn": ["abhängen", "beruhen", "entscheidend sein", "sich richten"], "ex": ["Das kommt darauf an."], "_exampleTrans": {"en": "That depends.", "tr": "Bu duruma bağlı.", "ru": "Это зависит от обстоятельств.", "uk": "Це залежить від обставин.", "es": "Eso depende.", "fa": "این بستگی دارد.", "ar": "هذا يتوقف على الأمر."}}, {"id": "vap_7b989b6a0e16", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "antworten + auf", "cat": "vp", "syn": ["erwidern", "entgegnen", "reagieren", "zurückschreiben"], "ex": ["Antworten Sie bitte auf meine Frage."], "_exampleTrans": {"en": "Please answer my question.", "tr": "Lütfen soruma cevap verin.", "ru": "Пожалуйста, ответьте на мой вопрос.", "uk": "Будь ласка, дайте відповідь на моє запитання.", "es": "Por favor, responda a mi pregunta.", "fa": "لطفاً به سؤال من پاسخ دهید.", "ar": "من فضلك أجب عن سؤالي."}}, {"id": "vap_beacfee71944", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "aufpassen + auf", "cat": "vp", "syn": ["achtgeben", "beachten", "hüten", "wachsam sein"], "ex": ["Sie sollten besser auf Ihren Schlüssel aufpassen. Hier wird oft geklaut."], "_exampleTrans": {"en": "You should take better care of your key. Things are often stolen here.", "tr": "Anahtarınıza daha iyi dikkat etmelisiniz. Burada sık sık hırsızlık olur.", "ru": "Вам следует лучше следить за своим ключом. Здесь часто воруют.", "uk": "Вам слід краще пильнувати свій ключ. Тут часто крадуть.", "es": "Debería cuidar mejor su llave. Aquí roban a menudo.", "fa": "بهتر است بیشتر مراقب کلیدتان باشید. اینجا زیاد دزدی می‌شود.", "ar": "ينبغي أن تنتبه أكثر إلى مفتاحك. هنا تُسرق الأشياء كثيرًا."}}, {"id": "vap_17375f1adf09", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich auswirken + auf", "cat": "vp", "syn": ["beeinflussen", "wirken", "Folgen haben", "sich niederschlagen"], "ex": ["Seine Müdigkeit hat sich auf seine Leistung ausgewirkt."], "_exampleTrans": {"en": "His tiredness affected his performance.", "tr": "Yorgunluğu performansını etkiledi.", "ru": "Его усталость сказалась на его результатах.", "uk": "Його втома позначилася на його результативності.", "es": "Su cansancio afectó a su rendimiento.", "fa": "خستگی‌اش بر عملکردش تأثیر گذاشت.", "ar": "أثّر تعبه في أدائه."}}, {"id": "vap_50dcae568a73", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich beziehen + auf", "cat": "vp", "syn": ["sich beziehen", "verweisen", "referieren", "Bezug nehmen"], "ex": ["Ich beziehe mich auf Ihren Brief vom 23. Mai."], "_exampleTrans": {"en": "I refer to your letter of 23 May.", "tr": "23 Mayıs tarihli mektubunuza atıfta bulunuyorum.", "ru": "Я ссылаюсь на Ваше письмо от 23 мая.", "uk": "Я посилаюся на Ваш лист від 23 травня.", "es": "Me refiero a su carta del 23 de mayo.", "fa": "من به نامهٔ شما مورخ ۲۳ مه اشاره می‌کنم.", "ar": "أشير إلى رسالتكم المؤرخة في 23 مايو."}}, {"id": "vap_239ca42d81c7", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich einigen + auf", "cat": "vp", "syn": ["vereinbaren", "sich verständigen", "übereinkommen", "Konsens finden"], "ex": ["Sie haben sich auf die Projektmeilensteine geeinigt."], "_exampleTrans": {"en": "They agreed on the project milestones.", "tr": "Proje kilometre taşları üzerinde anlaştılar.", "ru": "Они договорились о контрольных этапах проекта.", "uk": "Вони домовилися про етапні цілі проєкту.", "es": "Se pusieron de acuerdo sobre los hitos del proyecto.", "fa": "آن‌ها دربارهٔ نقاط عطف پروژه به توافق رسیدند.", "ar": "اتفقوا على معالم المشروع."}}, {"id": "vap_0fd24edbe1c6", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich einlassen + auf", "cat": "vp", "syn": ["sich einlassen", "akzeptieren", "eingehen", "sich beteiligen"], "ex": ["Er hat sich nicht auf das Angebot eingelassen."], "_exampleTrans": {"en": "He did not accept the offer.", "tr": "Teklifi kabul etmedi.", "ru": "Он не согласился на предложение.", "uk": "Він не погодився на пропозицію.", "es": "Él no aceptó la oferta.", "fa": "او پیشنهاد را نپذیرفت.", "ar": "لم يقبل العرض."}}, {"id": "vap_1633853bae76", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich einstellen + auf", "cat": "vp", "syn": ["anpassen", "sich vorbereiten", "umstellen", "ausrichten"], "ex": ["Wir müssen uns auf die neue Situation einstellen."], "_exampleTrans": {"en": "We have to adapt to the new situation.", "tr": "Yeni duruma uyum sağlamalıyız.", "ru": "Мы должны приспособиться к новой ситуации.", "uk": "Ми мусимо пристосуватися до нової ситуації.", "es": "Tenemos que adaptarnos a la nueva situación.", "fa": "ما باید خود را با وضعیت جدید وفق دهیم.", "ar": "علينا أن نتكيف مع الوضع الجديد."}}, {"id": "vap_d810588e2b93", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich einstimmen + auf", "cat": "vp", "syn": ["vorbereiten", "einstimmen", "in Stimmung bringen", "hinführen"], "ex": ["Wir können uns jetzt auf den Urlaub einstimmen."], "_exampleTrans": {"en": "We can now get ourselves in the mood for the holiday.", "tr": "Şimdi tatil havasına girebiliriz.", "ru": "Теперь мы можем настроиться на отпуск.", "uk": "Тепер ми можемо налаштуватися на відпустку.", "es": "Ahora podemos ir preparándonos para las vacaciones.", "fa": "حالا می‌توانیم خودمان را برای تعطیلات آماده کنیم.", "ar": "يمكننا الآن أن نهيئ أنفسنا للعطلة."}}, {"id": "vap_ef4d9721c8d5", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich freuen + auf/über", "cat": "vp", "syn": ["sich freuen", "sich begeistern", "glücklich sein", "erfreut sein"], "ex": ["Wir freuen uns auf den Urlaub."], "_exampleTrans": {"en": "We are looking forward to the holiday.", "tr": "Tatil için sabırsızlanıyoruz.", "ru": "Мы радуемся предстоящему отпуску.", "uk": "Ми з нетерпінням чекаємо на відпустку.", "es": "Estamos deseando que lleguen las vacaciones.", "fa": "ما مشتاق تعطیلات هستیم.", "ar": "نحن نتطلع إلى العطلة."}}, {"id": "vap_a7b5eabe53b1", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "hinweisen + auf", "cat": "vp", "syn": ["aufmerksam machen", "zeigen", "verweisen", "anmerken"], "ex": ["Sie hat ihn auf die Projektrisiken hingewiesen."], "_exampleTrans": {"en": "She pointed out the project risks to him.", "tr": "Ona proje risklerini hatırlattı.", "ru": "Она указала ему на риски проекта.", "uk": "Вона вказала йому на ризики проєкту.", "es": "Ella le señaló los riesgos del proyecto.", "fa": "او خطرات پروژه را به او گوشزد کرد.", "ar": "نبّهته إلى مخاطر المشروع."}}, {"id": "vap_d1ed0dbad8b9", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "hoffen + auf", "cat": "vp", "syn": ["erwarten", "wünschen", "vertrauen", "hoffen"], "ex": ["Sie hofft auf eine schnelle Antwort."], "_exampleTrans": {"en": "She hopes for a quick answer.", "tr": "Hızlı bir cevap umuyor.", "ru": "Она надеется на быстрый ответ.", "uk": "Вона сподівається на швидку відповідь.", "es": "Ella espera una respuesta rápida.", "fa": "او به پاسخ سریع امیدوار است.", "ar": "إنها تأمل في رد سريع."}}, {"id": "vap_135892e5ad38", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "kommen + auf/zu", "cat": "vp", "syn": ["gelangen", "entstehen", "eintreten", "kommen"], "ex": ["Wie sind Sie auf diesen Vorschlag gekommen?"], "_exampleTrans": {"en": "How did you come up with this proposal?", "tr": "Bu öneriyi nasıl buldunuz?", "ru": "Как Вы пришли к этому предложению?", "uk": "Як Ви дійшли до цієї пропозиції?", "es": "¿Cómo se le ocurrió esta propuesta?", "fa": "چطور به این پیشنهاد رسیدید؟", "ar": "كيف توصلتم إلى هذا الاقتراح؟"}}, {"id": "vap_56c842330129", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich konzentrieren + auf", "cat": "vp", "syn": ["fokussieren", "sich sammeln", "die Aufmerksamkeit richten", "sich konzentrieren"], "ex": ["Ich will mich ganz auf die Prüfung konzentrieren."], "_exampleTrans": {"en": "I want to concentrate entirely on the exam.", "tr": "Tamamen sınava odaklanmak istiyorum.", "ru": "Я хочу полностью сосредоточиться на экзамене.", "uk": "Я хочу повністю зосередитися на іспиті.", "es": "Quiero concentrarme por completo en el examen.", "fa": "می‌خواهم کاملاً روی امتحان تمرکز کنم.", "ar": "أريد أن أركز تمامًا على الامتحان."}}, {"id": "vap_7adaa9f70f44", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "reagieren + auf", "cat": "vp", "syn": ["antworten", "erwidern", "reagieren", "Stellung nehmen"], "ex": ["Wir müssen schnell auf seine Frage reagieren."], "_exampleTrans": {"en": "We have to react quickly to his question.", "tr": "Onun sorusuna hızlı tepki vermeliyiz.", "ru": "Мы должны быстро отреагировать на его вопрос.", "uk": "Ми маємо швидко відреагувати на його запитання.", "es": "Tenemos que reaccionar rápidamente a su pregunta.", "fa": "ما باید سریع به سؤال او واکنش نشان دهیم.", "ar": "علينا أن نرد بسرعة على سؤاله."}}, {"id": "vap_e4f4bde48579", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "stellen + auf", "cat": "vp", "syn": ["einstellen", "setzen", "platzieren", "stellen"], "ex": ["Stell den Schalter auf Stufe 3."], "_exampleTrans": {"en": "Set the switch to level 3.", "tr": "Düğmeyi 3. kademeye ayarla.", "ru": "Поставь переключатель на уровень 3.", "uk": "Постав перемикач на рівень 3.", "es": "Pon el interruptor en el nivel 3.", "fa": "کلید را روی سطح ۳ بگذار.", "ar": "اضبط المفتاح على المستوى 3."}}, {"id": "vap_adf289cc8fd3", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich verlassen + auf", "cat": "vp", "syn": ["vertrauen", "bauen auf", "sich stützen", "sich verlassen"], "ex": ["Sie können sich auf mich verlassen."], "_exampleTrans": {"en": "You can rely on me.", "tr": "Bana güvenebilirsiniz.", "ru": "Вы можете положиться на меня.", "uk": "Ви можете на мене покластися.", "es": "Puede contar conmigo.", "fa": "می‌توانید روی من حساب کنید.", "ar": "يمكنكم الاعتماد عليّ."}}, {"id": "vap_18c02f3d026b", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "verzichten + auf", "cat": "vp", "syn": ["aufgeben", "entsagen", "verzichten", "nicht in Anspruch nehmen"], "ex": ["Er kann auf seine Kaffeepause heute nicht verzichten."], "_exampleTrans": {"en": "He cannot do without his coffee break today.", "tr": "Bugün kahve molasından vazgeçemez.", "ru": "Сегодня он не может отказаться от перерыва на кофе.", "uk": "Сьогодні він не може відмовитися від кавової перерви.", "es": "Hoy no puede prescindir de su pausa para el café.", "fa": "او امروز نمی‌تواند از استراحت قهوه‌اش صرف‌نظر کند.", "ar": "لا يستطيع اليوم الاستغناء عن استراحة القهوة."}}, {"id": "vap_5400f7d40f35", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich vorbereiten + auf", "cat": "vp", "syn": ["präparieren", "planen", "sich rüsten", "vorbereiten"], "ex": ["Wir müssen uns auf das Gespräch vorbereiten."], "_exampleTrans": {"en": "We have to prepare for the meeting.", "tr": "Görüşmeye hazırlanmalıyız.", "ru": "Мы должны подготовиться к разговору.", "uk": "Ми маємо підготуватися до розмови.", "es": "Tenemos que prepararnos para la conversación.", "fa": "ما باید برای گفت‌وگو آماده شویم.", "ar": "علينا أن نستعد للمحادثة."}}, {"id": "vap_a20e979b13d6", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "warten + auf", "cat": "vp", "syn": ["abwarten", "erwarten", "warten", "ausharren"], "ex": ["Fabian wartet auf seinen Vorgesetzten."], "_exampleTrans": {"en": "Fabian is waiting for his supervisor.", "tr": "Fabian amirini bekliyor.", "ru": "Фабиан ждёт своего начальника.", "uk": "Фабіан чекає на свого керівника.", "es": "Fabian espera a su superior.", "fa": "فابیان منتظر سرپرستش است.", "ar": "ينتظر فابيان مشرفه."}}, {"id": "vap_9569e5c16876", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "wirken + auf", "cat": "vp", "syn": ["erscheinen", "beeinflussen", "wirken", "Eindruck machen"], "ex": ["Er wirkt auf mich sympathisch und kompetent."], "_exampleTrans": {"en": "He seems sympathetic and competent to me.", "tr": "Bana sempatik ve yetkin görünüyor.", "ru": "Он кажется мне симпатичным и компетентным.", "uk": "Він здається мені симпатичним і компетентним.", "es": "Me parece simpático y competente.", "fa": "به نظر من او دوست‌داشتنی و شایسته است.", "ar": "يبدو لي لطيفًا وكفؤًا."}}, {"id": "vap_b659b3a4042f", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "zukommen + auf", "cat": "vp", "syn": ["sich nähern", "bevorstehen", "entgegenkommen", "zukommen"], "ex": ["Ich sehe einige Probleme auf uns zukommen."], "_exampleTrans": {"en": "I see some problems coming toward us.", "tr": "Bazı sorunların bize doğru geldiğini görüyorum.", "ru": "Я вижу, что к нам приближаются некоторые проблемы.", "uk": "Я бачу, що на нас насуваються деякі проблеми.", "es": "Veo que se nos vienen encima algunos problemas.", "fa": "می‌بینم چند مشکل به سوی ما می‌آیند.", "ar": "أرى بعض المشكلات مقبلة علينا."}}, {"id": "vap_19e8bd462ef7", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "bestehen + aus", "cat": "vp", "syn": ["sich zusammensetzen", "existieren", "bestehen bleiben", "beruhen"], "ex": ["Mein Vortrag besteht aus drei Teilen."], "_exampleTrans": {"en": "My presentation consists of three parts.", "tr": "Sunumum üç bölümden oluşuyor.", "ru": "Мой доклад состоит из трёх частей.", "uk": "Моя доповідь складається з трьох частин.", "es": "Mi presentación consta de tres partes.", "fa": "سخنرانی من از سه بخش تشکیل شده است.", "ar": "يتكوّن عرضي من ثلاثة أجزاء."}}, {"id": "vap_e4817dfe368b", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "herauskommen + aus", "cat": "vp", "syn": ["hinauskommen", "austreten", "hervortreten", "erscheinen"], "ex": ["Die Mitarbeiter sind aus ihren Büros herausgekommen."], "_exampleTrans": {"en": "The employees came out of their offices.", "tr": "Çalışanlar ofislerinden çıktı.", "ru": "Сотрудники вышли из своих офисов.", "uk": "Працівники вийшли зі своїх офісів.", "es": "Los empleados salieron de sus oficinas.", "fa": "کارمندان از دفترهایشان بیرون آمدند.", "ar": "خرج الموظفون من مكاتبهم."}}, {"id": "vap_b461249a39b9", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich zurückziehen + aus/von", "cat": "vp", "syn": ["sich zurückziehen", "austreten", "sich entfernen", "zurücktreten"], "ex": ["Sie hat sich aus der Geschäftsführung zurückgezogen."], "_exampleTrans": {"en": "She withdrew from the management.", "tr": "Yönetimden çekildi.", "ru": "Она вышла из руководства.", "uk": "Вона вийшла зі складу керівництва.", "es": "Ella se retiró de la dirección.", "fa": "او از مدیریت کناره‌گیری کرد.", "ar": "انسحبت من الإدارة."}}, {"id": "vap_f12318557fd0", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich zusammensetzen + aus", "cat": "vp", "syn": ["bestehen", "sich zusammensetzen", "gebildet sein", "zusammengesetzt sein"], "ex": ["Die Luft setzt sich aus verschiedenen Gasen zusammen."], "_exampleTrans": {"en": "Air is composed of various gases.", "tr": "Hava çeşitli gazlardan oluşur.", "ru": "Воздух состоит из различных газов.", "uk": "Повітря складається з різних газів.", "es": "El aire se compone de diferentes gases.", "fa": "هوا از گازهای مختلف تشکیل شده است.", "ar": "يتكوّن الهواء من غازات مختلفة."}}, {"id": "vap_07622b4f2d11", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "verweilen + bei", "cat": "vp", "syn": ["bleiben", "sich aufhalten", "verweilen", "verbringen"], "ex": ["Er verweilte ein paar Tage bei seinen Freunden."], "_exampleTrans": {"en": "He stayed with his friends for a few days.", "tr": "Birkaç gün arkadaşlarının yanında kaldı.", "ru": "Он провёл несколько дней у своих друзей.", "uk": "Він пробув кілька днів у своїх друзів.", "es": "Se quedó unos días con sus amigos.", "fa": "او چند روز نزد دوستانش ماند.", "ar": "مكث بضعة أيام عند أصدقائه."}}, {"id": "vap_7588eb315d92", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich erstrecken + bis/von", "cat": "vp", "syn": ["sich ausdehnen", "reichen", "verlaufen", "sich hinziehen"], "ex": ["Die Alpen erstrecken sich von Frankreich bis (nach) Slowenien."], "_exampleTrans": {"en": "The Alps extend from France to Slovenia.", "tr": "Alpler Fransa’dan Slovenya’ya kadar uzanır.", "ru": "Альпы простираются от Франции до Словении.", "uk": "Альпи простягаються від Франції до Словенії.", "es": "Los Alpes se extienden desde Francia hasta Eslovenia.", "fa": "کوه‌های آلپ از فرانسه تا اسلوونی امتداد دارند.", "ar": "تمتد جبال الألب من فرنسا إلى سلوفينيا."}}, {"id": "vap_eeac36893978", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich auszeichnen + durch", "cat": "vp", "syn": ["kennzeichnen", "hervorheben", "charakterisieren", "prädestinieren"], "ex": ["Sie zeichnet sich durch Genauigkeit aus."], "_exampleTrans": {"en": "She distinguishes herself by her precision.", "tr": "Hassasiyetiyle öne çıkar.", "ru": "Она отличается точностью.", "uk": "Вона вирізняється точністю.", "es": "Ella se distingue por su precisión.", "fa": "او با دقتش متمایز می‌شود.", "ar": "تتميّز بالدقة."}}, {"id": "vap_7b0cf8765a0c", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "beeindrucken + durch/mit", "cat": "vp", "syn": ["imponieren", "faszinieren", "begeistern", "Eindruck machen"], "ex": ["Sie beeindruckte ihre Chefin durch ihr Können."], "_exampleTrans": {"en": "She impressed her boss with her ability.", "tr": "Yeteneğiyle patronunu etkiledi.", "ru": "Она впечатлила свою начальницу своим умением.", "uk": "Вона вразила свою начальницю своїми вміннями.", "es": "Impresionó a su jefa con su habilidad.", "fa": "او با توانایی‌اش رئیسش را تحت تأثیر قرار داد.", "ar": "أثّرت في مديرتها بمهارتها."}}, {"id": "vap_9b19bc2d0e1b", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "ersetzen + durch", "cat": "vp", "syn": ["austauschen", "substituieren", "ablösen", "an die Stelle setzen"], "ex": ["Alle Laptops wurden durch neue Tablets ersetzt."], "_exampleTrans": {"en": "All laptops were replaced by new tablets.", "tr": "Tüm dizüstü bilgisayarlar yeni tabletlerle değiştirildi.", "ru": "Все ноутбуки были заменены новыми планшетами.", "uk": "Усі ноутбуки були замінені новими планшетами.", "es": "Todos los portátiles fueron sustituidos por nuevas tabletas.", "fa": "همهٔ لپ‌تاپ‌ها با تبلت‌های جدید جایگزین شدند.", "ar": "استُبدلت جميع الحواسيب المحمولة بأجهزة لوحية جديدة."}}, {"id": "vap_e29872c2b30e", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "ausgeben + für", "cat": "vp", "syn": ["aufwenden", "investieren", "bezahlen", "verausgaben"], "ex": ["Die Firma gibt viel Geld für Weiterbildung aus."], "_exampleTrans": {"en": "The company spends a lot of money on continuing education.", "tr": "Şirket sürekli eğitim için çok para harcıyor.", "ru": "Фирма тратит много денег на повышение квалификации.", "uk": "Фірма витрачає багато грошей на підвищення кваліфікації.", "es": "La empresa gasta mucho dinero en formación continua.", "fa": "شرکت پول زیادی برای آموزش‌های تکمیلی خرج می‌کند.", "ar": "تنفق الشركة الكثير من المال على التعليم المستمر."}}, {"id": "vap_05dc2cf71fdb", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich begeistern + für", "cat": "vp", "syn": ["entzücken", "faszinieren", "mitreißen", "begeistern"], "ex": ["Er hat sich für die neue Technik begeistert."], "_exampleTrans": {"en": "He became enthusiastic about the new technology.", "tr": "Yeni teknolojiye büyük ilgi duydu.", "ru": "Он увлёкся новой технологией.", "uk": "Він захопився новою технікою.", "es": "Se entusiasmó por la nueva tecnología.", "fa": "او به فناوری جدید علاقه‌مند شد.", "ar": "تحمّس للتقنية الجديدة."}}, {"id": "vap_92254cf8c13e", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich einsetzen + für", "cat": "vp", "syn": ["sich engagieren", "eintreten", "unterstützen", "verwenden"], "ex": ["Sie hat sich aktiv für ihren Kollegen eingesetzt."], "_exampleTrans": {"en": "She actively stood up for her colleague.", "tr": "Meslektaşı için aktif olarak çaba gösterdi.", "ru": "Она активно заступилась за своего коллегу.", "uk": "Вона активно підтримала свого колегу.", "es": "Ella defendió activamente a su colega.", "fa": "او فعالانه از همکارش حمایت کرد.", "ar": "دافعت بنشاط عن زميلها."}}, {"id": "vap_79991bef1850", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich engagieren + für", "cat": "vp", "syn": ["sich einsetzen", "mitwirken", "sich beteiligen", "aktiv werden"], "ex": ["Ich engagiere mich für das Jugendtheater in unserer Stadt."], "_exampleTrans": {"en": "I am involved in the youth theater in our city.", "tr": "Şehrimizdeki gençlik tiyatrosunda gönüllü çalışıyorum.", "ru": "Я занимаюсь молодёжным театром в нашем городе.", "uk": "Я займаюся молодіжним театром у нашому місті.", "es": "Me comprometo con el teatro juvenil de nuestra ciudad.", "fa": "من در تئاتر جوانان شهرمان فعالیت می‌کنم.", "ar": "أشارك في مسرح الشباب في مدينتنا."}}, {"id": "vap_1b58fddd4ce4", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich entscheiden + für", "cat": "vp", "syn": ["wählen", "beschließen", "sich festlegen", "eine Wahl treffen"], "ex": ["Sie hat sich für das billigere Angebot entschieden."], "_exampleTrans": {"en": "She decided in favor of the cheaper offer.", "tr": "Daha ucuz teklifi seçti.", "ru": "Она решила выбрать более дешёвое предложение.", "uk": "Вона обрала дешевшу пропозицію.", "es": "Ella se decidió por la oferta más barata.", "fa": "او پیشنهاد ارزان‌تر را انتخاب کرد.", "ar": "اختارت العرض الأرخص."}}, {"id": "vap_bf1859bb1b59", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich entschuldigen + für", "cat": "vp", "syn": ["um Verzeihung bitten", "sich entschuldigen", "bedauern", "Abbitte leisten"], "ex": ["Ich entschuldige mich für diesen Fehler."], "_exampleTrans": {"en": "I apologize for this mistake.", "tr": "Bu hata için özür dilerim.", "ru": "Я извиняюсь за эту ошибку.", "uk": "Я перепрошую за цю помилку.", "es": "Me disculpo por este error.", "fa": "من بابت این اشتباه عذرخواهی می‌کنم.", "ar": "أعتذر عن هذا الخطأ."}}, {"id": "vap_80fcc05e8558", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "erwärmen + für", "cat": "vp", "syn": ["sich begeistern", "Interesse entwickeln", "warmwerden", "Sympathie fassen"], "ex": ["Er konnte sich nicht für seinen neuen Chef erwärmen."], "_exampleTrans": {"en": "He could not warm to his new boss.", "tr": "Yeni patronuna bir türlü ısınamadı.", "ru": "Он не смог проникнуться симпатией к своему новому начальнику.", "uk": "Він не зміг прихильно поставитися до свого нового начальника.", "es": "No pudo simpatizar con su nuevo jefe.", "fa": "او نتوانست به رئیس جدیدش علاقه‌مند شود.", "ar": "لم يستطع أن يتقبّل مديره الجديد."}}, {"id": "vap_71fe4139d7b6", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "halten + für/von", "cat": "vp", "syn": ["meinen", "betrachten", "ansehen", "einschätzen"], "ex": ["Wir halten Innovationen für ein wichtiges Thema."], "_exampleTrans": {"en": "We consider innovations an important topic.", "tr": "İnovasyonları önemli bir konu olarak görüyoruz.", "ru": "Мы считаем инновации важной темой.", "uk": "Ми вважаємо інновації важливою темою.", "es": "Consideramos las innovaciones un tema importante.", "fa": "ما نوآوری‌ها را موضوعی مهم می‌دانیم.", "ar": "نعدّ الابتكارات موضوعًا مهمًا."}}, {"id": "vap_b5f33d12a927", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich interessieren + für", "cat": "vp", "syn": ["sich begeistern", "neugierig sein", "Interesse haben", "sich interessieren"], "ex": ["Sie interessiert sich sehr für die Weiterbildung."], "_exampleTrans": {"en": "She is very interested in continuing education.", "tr": "Sürekli eğitime çok ilgi duyuyor.", "ru": "Она очень интересуется повышением квалификации.", "uk": "Вона дуже цікавиться підвищенням кваліфікації.", "es": "Ella está muy interesada en la formación continua.", "fa": "او به آموزش تکمیلی بسیار علاقه‌مند است.", "ar": "إنها مهتمة جدًا بالتعليم المستمر."}}, {"id": "vap_4ab50c84c08b", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "kämpfen + für/gegen", "cat": "vp", "syn": ["streiten", "ringen", "sich einsetzen", "kämpfen"], "ex": ["Sie kämpft für die Anerkennung ihres Schulabschlusses."], "_exampleTrans": {"en": "She is fighting for the recognition of her school-leaving certificate.", "tr": "Okul bitirme belgesinin tanınması için mücadele ediyor.", "ru": "Она борется за признание своего школьного аттестата.", "uk": "Вона бореться за визнання свого шкільного атестата.", "es": "Ella lucha por el reconocimiento de su título escolar.", "fa": "او برای به رسمیت شناخته شدن مدرک پایان مدرسه‌اش مبارزه می‌کند.", "ar": "تناضل من أجل الاعتراف بشهادة تخرّجها المدرسية."}}, {"id": "vap_98d965ec68a1", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "plädieren + für", "cat": "vp", "syn": ["eintreten", "sich aussprechen", "befürworten", "argumentieren"], "ex": ["Er plädierte für die Anmietung neuer Büros."], "_exampleTrans": {"en": "He argued in favor of renting new offices.", "tr": "Yeni ofislerin kiralanmasını savundu.", "ru": "Он выступил за аренду новых офисов.", "uk": "Він виступив за оренду нових офісів.", "es": "Él abogó por el alquiler de nuevas oficinas.", "fa": "او از اجارهٔ دفترهای جدید دفاع کرد.", "ar": "دعا إلى استئجار مكاتب جديدة."}}, {"id": "vap_ac1887714f4f", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sorgen + für", "cat": "vp", "syn": ["verursachen", "bewirken", "kümmern", "sicherstellen"], "ex": ["Ihr Auftritt sorgte für eine Überraschung."], "_exampleTrans": {"en": "Her appearance caused a surprise.", "tr": "Onun sahneye çıkışı bir sürprize yol açtı.", "ru": "Её выступление вызвало удивление.", "uk": "Її виступ спричинив несподіванку.", "es": "Su aparición causó una sorpresa.", "fa": "حضور او باعث شگفتی شد.", "ar": "أثار ظهورها مفاجأة."}}, {"id": "vap_2da49199ca96", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "stimmen + für/gegen", "cat": "vp", "syn": ["abstimmen", "votieren", "zustimmen", "stimmen"], "ex": ["Viele stimmten für den neuen Plan."], "_exampleTrans": {"en": "Many voted for the new plan.", "tr": "Birçok kişi yeni plan lehine oy kullandı.", "ru": "Многие проголосовали за новый план.", "uk": "Багато хто проголосував за новий план.", "es": "Muchos votaron a favor del nuevo plan.", "fa": "بسیاری به طرح جدید رأی موافق دادند.", "ar": "صوّت كثيرون لصالح الخطة الجديدة."}}, {"id": "vap_dcc48b77a64e", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "tun + für/gegen", "cat": "vp", "syn": ["machen", "handeln", "unternehmen", "tun"], "ex": ["Wir tun alles für die Einhaltung des Terminplans."], "_exampleTrans": {"en": "We are doing everything to comply with the schedule.", "tr": "Termin planına uyulması için her şeyi yapıyoruz.", "ru": "Мы делаем всё для соблюдения графика.", "uk": "Ми робимо все для дотримання графіка.", "es": "Hacemos todo lo posible para cumplir el calendario.", "fa": "ما برای رعایت برنامهٔ زمانی همه کار می‌کنیم.", "ar": "نفعل كل شيء للالتزام بالجدول الزمني."}}, {"id": "vap_66a8883aa33f", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "votieren + für/gegen", "cat": "vp", "syn": ["abstimmen", "stimmen", "votieren", "sich aussprechen"], "ex": ["Sie votierte für eine Ausweitung der Produktion."], "_exampleTrans": {"en": "She voted in favor of expanding production.", "tr": "Üretimin genişletilmesi lehine oy kullandı.", "ru": "Она проголосовала за расширение производства.", "uk": "Вона проголосувала за розширення виробництва.", "es": "Votó a favor de ampliar la producción.", "fa": "او به گسترش تولید رأی موافق داد.", "ar": "صوّتت لصالح توسيع الإنتاج."}}, {"id": "vap_2ea67577ad0e", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich durchsetzen + gegen", "cat": "vp", "syn": ["sich behaupten", "sich durchbringen", "sich behaupten", "Erfolg haben"], "ex": ["Warum setzen Sie sich nicht einfach gegen Ihre Kollegen durch?"], "_exampleTrans": {"en": "Why don't you simply assert yourself against your colleagues?", "tr": "Neden meslektaşlarınıza karşı kendinizi kolayca kabul ettirmiyorsunuz?", "ru": "Почему Вы просто не настоите на своём в отношении коллег?", "uk": "Чому Ви просто не відстоюєте себе перед колегами?", "es": "¿Por qué no se impone simplemente frente a sus colegas?", "fa": "چرا به‌سادگی در برابر همکارانتان حرف خود را پیش نمی‌برید؟", "ar": "لماذا لا تفرض نفسك ببساطة أمام زملائك؟"}}, {"id": "vap_a4ac1b5b20fb", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "kämpfen + gegen/für", "cat": "vp", "syn": ["streiten", "ringen", "sich einsetzen", "kämpfen"], "ex": ["Wir müssen gegen Intoleranz kämpfen."], "_exampleTrans": {"en": "We have to fight against intolerance.", "tr": "Hoşgörüsüzlüğe karşı mücadele etmeliyiz.", "ru": "Мы должны бороться с нетерпимостью.", "uk": "Ми мусимо боротися з нетерпимістю.", "es": "Tenemos que luchar contra la intolerancia.", "fa": "ما باید با عدم تحمل مبارزه کنیم.", "ar": "علينا أن نحارب التعصّب."}}, {"id": "vap_b4ee474869ad", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "protestieren + gegen", "cat": "vp", "syn": ["demonstrieren", "Einspruch erheben", "protestieren", "sich wehren"], "ex": ["Die Mitarbeitenden protestierten gegen die Entlassungen."], "_exampleTrans": {"en": "The employees protested against the dismissals.", "tr": "Çalışanlar işten çıkarmalara karşı protesto etti.", "ru": "Сотрудники протестовали против увольнений.", "uk": "Працівники протестували проти звільнень.", "es": "Los empleados protestaron contra los despidos.", "fa": "کارکنان علیه اخراج‌ها اعتراض کردند.", "ar": "احتج الموظفون على عمليات الفصل."}}, {"id": "vap_c3b2d8d3c02c", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "stimmen + gegen/für", "cat": "vp", "syn": ["abstimmen", "votieren", "zustimmen", "stimmen"], "ex": ["Einige stimmten gegen den Plan."], "_exampleTrans": {"en": "Some voted against the plan.", "tr": "Bazıları plana karşı oy kullandı.", "ru": "Некоторые проголосовали против плана.", "uk": "Дехто проголосував проти плану.", "es": "Algunos votaron en contra del plan.", "fa": "برخی علیه طرح رأی دادند.", "ar": "صوّت بعضهم ضد الخطة."}}, {"id": "vap_b7f67ab23996", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "tun + gegen/für", "cat": "vp", "syn": ["machen", "handeln", "unternehmen", "tun"], "ex": ["Sie sollten etwas gegen Ihre Erkältung tun."], "_exampleTrans": {"en": "You should do something about your cold.", "tr": "Soğuk algınlığınız için bir şeyler yapmalısınız.", "ru": "Вам следует что-нибудь сделать против своей простуды.", "uk": "Вам слід щось зробити проти своєї застуди.", "es": "Debería hacer algo contra su resfriado.", "fa": "شما باید برای سرماخوردگی‌تان کاری بکنید.", "ar": "ينبغي أن تفعل شيئًا لمعالجة نزلتك البردية."}}, {"id": "vap_282221d510c4", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich verteidigen + gegen", "cat": "vp", "syn": ["sich wehren", "rechtfertigen", "verteidigen", "schützen"], "ex": ["Er hat sich gegen die Vorwürfe verteidigt."], "_exampleTrans": {"en": "He defended himself against the accusations.", "tr": "Suçlamalara karşı kendini savundu.", "ru": "Он защитился от обвинений.", "uk": "Він захистився від звинувачень.", "es": "Se defendió de las acusaciones.", "fa": "او در برابر اتهامات از خود دفاع کرد.", "ar": "دافع عن نفسه ضد الاتهامات."}}, {"id": "vap_3716653b90de", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "verstoßen + gegen", "cat": "vp", "syn": ["verletzen", "missachten", "brechen", "verstoßen"], "ex": ["Sie haben gegen die Sicherheitsvorschriften verstoßen."], "_exampleTrans": {"en": "You have violated the safety regulations.", "tr": "Güvenlik talimatlarını ihlal ettiniz.", "ru": "Вы нарушили правила техники безопасности.", "uk": "Ви порушили правила безпеки.", "es": "Han infringido las normas de seguridad.", "fa": "شما مقررات ایمنی را نقض کرده‌اید.", "ar": "لقد خالفتم تعليمات السلامة."}}, {"id": "vap_7e0079aa0af0", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "votieren + gegen/für", "cat": "vp", "syn": ["abstimmen", "stimmen", "votieren", "sich aussprechen"], "ex": ["Er votierte gegen die Betriebsschließung."], "_exampleTrans": {"en": "He voted against the closure of the plant.", "tr": "İşletmenin kapatılmasına karşı oy kullandı.", "ru": "Он проголосовал против закрытия предприятия.", "uk": "Він проголосував проти закриття підприємства.", "es": "Votó en contra del cierre de la empresa.", "fa": "او علیه تعطیلی کارخانه رأی داد.", "ar": "صوّت ضد إغلاق المنشأة."}}, {"id": "vap_087831e96041", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich halten + in", "cat": "vp", "syn": ["meinen", "betrachten", "ansehen", "einschätzen"], "ex": ["Sie hat sich in der Prüfung sehr gut gehalten."], "_exampleTrans": {"en": "She did very well in the exam.", "tr": "Sınavda kendini çok iyi gösterdi.", "ru": "На экзамене она показала себя очень хорошо.", "uk": "На іспиті вона дуже добре трималася.", "es": "Ella se desenvolvió muy bien en el examen.", "fa": "او در امتحان خیلی خوب عمل کرد.", "ar": "أدّت أداءً جيدًا جدًا في الامتحان."}}, {"id": "vap_02b190049803", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich hineinversetzen + in", "cat": "vp", "syn": ["sich einfühlen", "sich versetzen", "nachvollziehen", "empathisch verstehen"], "ex": ["Ich kann mich gut in den Chef hineinversetzen."], "_exampleTrans": {"en": "I can put myself in the boss's position well.", "tr": "Kendimi patronun yerine iyi koyabiliyorum.", "ru": "Я хорошо могу поставить себя на место начальника.", "uk": "Я добре можу поставити себе на місце начальника.", "es": "Puedo ponerme bien en el lugar del jefe.", "fa": "می‌توانم خودم را خوب جای رئیس بگذارم.", "ar": "أستطيع أن أضع نفسي جيدًا مكان المدير."}}, {"id": "vap_c227fdc7117f", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich integrieren + in", "cat": "vp", "syn": ["eingliedern", "einbinden", "aufnehmen", "integrieren"], "ex": ["Er hat sich gut in das neue Team integriert."], "_exampleTrans": {"en": "He integrated well into the new team.", "tr": "Yeni ekibe iyi uyum sağladı.", "ru": "Он хорошо интегрировался в новую команду.", "uk": "Він добре інтегрувався в нову команду.", "es": "Se integró bien en el nuevo equipo.", "fa": "او به‌خوبی در تیم جدید ادغام شد.", "ar": "اندمج جيدًا في الفريق الجديد."}}, {"id": "vap_8ea84facfeb1", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "investieren + in", "cat": "vp", "syn": ["anlegen", "einsetzen", "investieren", "Kapital aufwenden"], "ex": ["Der Staat sollte mehr in Elektroautos investieren."], "_exampleTrans": {"en": "The state should invest more in electric cars.", "tr": "Devlet elektrikli otomobillere daha fazla yatırım yapmalı.", "ru": "Государству следует больше инвестировать в электромобили.", "uk": "Держава має більше інвестувати в електромобілі.", "es": "El Estado debería invertir más en coches eléctricos.", "fa": "دولت باید بیشتر در خودروهای برقی سرمایه‌گذاری کند.", "ar": "ينبغي للدولة أن تستثمر أكثر في السيارات الكهربائية."}}, {"id": "vap_e020d69ea799", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "nachlassen + in", "cat": "vp", "syn": ["abnehmen", "zurückgehen", "schwächer werden", "sinken"], "ex": ["Er hat in seinen Leistungen leider sehr nachgelassen."], "_exampleTrans": {"en": "Unfortunately, his performance has declined a lot.", "tr": "Ne yazık ki performansı çok düştü.", "ru": "К сожалению, его результаты сильно ухудшились.", "uk": "На жаль, його результати значно погіршилися.", "es": "Lamentablemente, su rendimiento ha disminuido mucho.", "fa": "متأسفانه عملکرد او بسیار افت کرده است.", "ar": "للأسف تراجع أداؤه كثيرًا."}}, {"id": "vap_8adeaaeb950b", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "übereinstimmen + in", "cat": "vp", "syn": ["übereinkommen", "einig sein", "entsprechen", "übereinstimmen"], "ex": ["Die Mitarbeitenden stimmten in diesem Punkt überein."], "_exampleTrans": {"en": "The employees agreed on this point.", "tr": "Çalışanlar bu noktada aynı fikirdeydi.", "ru": "Сотрудники сошлись во мнении по этому пункту.", "uk": "Працівники зійшлися в цьому пункті.", "es": "Los empleados coincidieron en este punto.", "fa": "کارکنان در این مورد هم‌نظر بودند.", "ar": "اتفق الموظفون في هذه النقطة."}}, {"id": "vap_e4c9319616fa", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "umrechnen + in", "cat": "vp", "syn": ["konvertieren", "umwandeln", "berechnen", "umrechnen"], "ex": ["Die Bank hat die Dollar in Euro umgerechnet."], "_exampleTrans": {"en": "The bank converted the dollars into euros.", "tr": "Banka dolarları avroya çevirdi.", "ru": "Банк пересчитал доллары в евро.", "uk": "Банк перерахував долари в євро.", "es": "El banco convirtió los dólares en euros.", "fa": "بانک دلارها را به یورو تبدیل کرد.", "ar": "حوّل البنك الدولارات إلى يورو."}}, {"id": "vap_cfcd170f4208", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich abfinden + mit", "cat": "vp", "syn": ["akzeptieren", "hinnehmen", "sich arrangieren", "sich fügen"], "ex": ["Wir fanden uns mit der Situation ab."], "_exampleTrans": {"en": "We came to terms with the situation.", "tr": "Durumu kabullendik.", "ru": "Мы смирились с ситуацией.", "uk": "Ми змирилися із ситуацією.", "es": "Nos resignamos a la situación.", "fa": "ما با وضعیت کنار آمدیم.", "ar": "تصالحنا مع الوضع."}}, {"id": "vap_4363dbb16c3d", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich abmühen + mit", "cat": "vp", "syn": ["sich plagen", "sich abrackern", "sich anstrengen", "sich quälen"], "ex": ["Mit Informatik habe ich mich immer sehr abgemüht."], "_exampleTrans": {"en": "I have always struggled a lot with computer science.", "tr": "Bilişimle her zaman çok uğraştım.", "ru": "С информатикой мне всегда было очень трудно.", "uk": "З інформатикою мені завжди було дуже важко.", "es": "Siempre me he esforzado mucho con la informática.", "fa": "من همیشه با علوم کامپیوتر خیلی کلنجار رفته‌ام.", "ar": "لقد عانيت دائمًا كثيرًا مع علوم الحاسوب."}}, {"id": "vap_0ffdff1322fe", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "anfangen + mit", "cat": "vp", "syn": ["beginnen", "starten", "loslegen", "aufnehmen"], "ex": ["Wann fangen Sie mit der Arbeit an?"], "_exampleTrans": {"en": "When are you starting work?", "tr": "İşe ne zaman başlıyorsunuz?", "ru": "Когда Вы начинаете работу?", "uk": "Коли Ви починаєте роботу?", "es": "¿Cuándo empieza usted con el trabajo?", "fa": "کی کار را شروع می‌کنید؟", "ar": "متى تبدأون العمل؟"}}, {"id": "vap_cb7206980311", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "assoziieren + mit", "cat": "vp", "syn": ["verbinden", "verknüpfen", "in Verbindung bringen", "zuordnen"], "ex": ["Mit diesem Projekt assoziiert sie ungute Gefühle."], "_exampleTrans": {"en": "She associates bad feelings with this project.", "tr": "Bu projeyle kötü duygular ilişkilendiriyor.", "ru": "С этим проектом у неё связаны неприятные чувства.", "uk": "Вона пов’язує з цим проєктом неприємні почуття.", "es": "Ella asocia sentimientos negativos con este proyecto.", "fa": "او این پروژه را با احساسات ناخوشایند مرتبط می‌داند.", "ar": "تربط هذا المشروع بمشاعر سيئة."}}, {"id": "vap_afbe2d07b5e0", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "aufhören + mit", "cat": "vp", "syn": ["beenden", "einstellen", "stoppen", "unterlassen"], "ex": ["Hör endlich mit dem Gejammer auf!"], "_exampleTrans": {"en": "Stop whining at last!", "tr": "Artık şu sızlanmayı bırak!", "ru": "Перестань наконец ныть!", "uk": "Припини вже скиглити!", "es": "¡Deja por fin de quejarte!", "fa": "بالاخره دست از غر زدن بردار!", "ar": "كفّ أخيرًا عن التذمر!"}}, {"id": "vap_91a8b8ca164c", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich auseinandersetzen + mit", "cat": "vp", "syn": ["befassen", "behandeln", "diskutieren", "sich beschäftigen"], "ex": ["Wir müssen uns mit dem Thema auseinandersetzen."], "_exampleTrans": {"en": "We have to deal with the topic.", "tr": "Bu konuyla ilgilenmemiz gerekiyor.", "ru": "Мы должны заняться этой темой.", "uk": "Ми маємо розібратися з цією темою.", "es": "Tenemos que ocuparnos del tema.", "fa": "ما باید به این موضوع بپردازیم.", "ar": "علينا أن نتعامل مع هذا الموضوع."}}, {"id": "vap_de0fe7f16196", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich auskennen + mit", "cat": "vp", "syn": ["sich auskennen", "vertraut sein", "Bescheid wissen", "sich zurechtfinden"], "ex": ["Sie kennt sich mit der neuen Software gut aus."], "_exampleTrans": {"en": "She knows the new software well.", "tr": "Yeni yazılımı iyi biliyor.", "ru": "Она хорошо разбирается в новом программном обеспечении.", "uk": "Вона добре розуміється на новому програмному забезпеченні.", "es": "Ella conoce bien el nuevo software.", "fa": "او با نرم‌افزار جدید خوب آشناست.", "ar": "إنها متمكّنة من البرنامج الجديد."}}, {"id": "vap_c107dc8ce93a", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "ausstatten + mit", "cat": "vp", "syn": ["ausrüsten", "versehen", "bestücken", "einrichten"], "ex": ["Das Auto ist mit vielen Extras ausgestattet."], "_exampleTrans": {"en": "The car is equipped with many extras.", "tr": "Araba birçok ekstra donanımla donatılmış.", "ru": "Автомобиль оснащён множеством дополнительных опций.", "uk": "Автомобіль оснащений багатьма додатковими опціями.", "es": "El coche está equipado con muchos extras.", "fa": "خودرو به امکانات اضافی زیادی مجهز است.", "ar": "السيارة مجهزة بالعديد من الإضافات."}}, {"id": "vap_404d4ad5af65", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich austauschen + mit/über", "cat": "vp", "syn": ["kommunizieren", "sich besprechen", "Erfahrungen teilen", "sich beraten"], "ex": ["Sie tauschten sich mit den anderen Lernenden über ihre Erfahrungen aus."], "_exampleTrans": {"en": "They exchanged views with the other learners about their experiences.", "tr": "Diğer öğrenenlerle deneyimleri hakkında fikir alışverişinde bulundular.", "ru": "Они обменялись с другими учащимися опытом.", "uk": "Вони обмінялися з іншими учнями досвідом.", "es": "Intercambiaron opiniones con los demás aprendices sobre sus experiencias.", "fa": "آن‌ها با دیگر زبان‌آموزان دربارهٔ تجربه‌هایشان تبادل نظر کردند.", "ar": "تبادلوا الآراء مع المتعلمين الآخرين حول تجاربهم."}}, {"id": "vap_254aa16f3526", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "beauftragen + mit", "cat": "vp", "syn": ["bevollmächtigen", "anweisen", "betrauen", "delegieren"], "ex": ["Er wurde mit der Durchführung des Projekts beauftragt."], "_exampleTrans": {"en": "He was commissioned with carrying out the project.", "tr": "Projenin yürütülmesiyle görevlendirildi.", "ru": "Ему поручили выполнение проекта.", "uk": "Йому доручили виконання проєкту.", "es": "Se le encargó la ejecución del proyecto.", "fa": "اجرای پروژه به او سپرده شد.", "ar": "كُلّف بتنفيذ المشروع."}}, {"id": "vap_2815f5c35e21", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "beeindrucken + mit/durch", "cat": "vp", "syn": ["imponieren", "faszinieren", "begeistern", "Eindruck machen"], "ex": ["Sie beeindruckten ihre Kollegen mit ihrem fundierten Wissen."], "_exampleTrans": {"en": "They impressed their colleagues with their well-founded knowledge.", "tr": "Sağlam bilgileriyle meslektaşlarını etkilediler.", "ru": "Они впечатлили коллег своими основательными знаниями.", "uk": "Вони вразили колег своїми ґрунтовними знаннями.", "es": "Impresionaron a sus colegas con sus conocimientos fundados.", "fa": "آن‌ها با دانش مستدل خود همکارانشان را تحت تأثیر قرار دادند.", "ar": "أثّروا في زملائهم بمعرفتهم الراسخة."}}, {"id": "vap_478c19118282", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich befassen + mit", "cat": "vp", "syn": ["behandeln", "bearbeiten", "sich widmen", "sich beschäftigen"], "ex": ["Mit diesem Problem müssen wir uns bald befassen."], "_exampleTrans": {"en": "We will soon have to deal with this problem.", "tr": "Yakında bu sorunla ilgilenmemiz gerekecek.", "ru": "С этой проблемой нам скоро придётся заняться.", "uk": "Нам скоро доведеться зайнятися цією проблемою.", "es": "Pronto tendremos que ocuparnos de este problema.", "fa": "به‌زودی باید به این مشکل بپردازیم.", "ar": "سيتعين علينا قريبًا التعامل مع هذه المشكلة."}}, {"id": "vap_71e1d5546d40", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "beginnen + mit", "cat": "vp", "syn": ["anfangen", "starten", "loslegen", "eröffnen"], "ex": ["Wann beginnen Sie mit der Arbeit?"], "_exampleTrans": {"en": "When do you begin work?", "tr": "İşe ne zaman başlıyorsunuz?", "ru": "Когда Вы начинаете работу?", "uk": "Коли Ви починаєте роботу?", "es": "¿Cuándo empieza usted con el trabajo?", "fa": "کی کار را شروع می‌کنید؟", "ar": "متى تبدأون العمل؟"}}, {"id": "vap_febc2a514ecb", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "(sich) belohnen + mit", "cat": "vp", "syn": ["vergüten", "honorieren", "auszeichnen", "entschädigen"], "ex": ["Sie belohnt sich für die vielen Überstunden mit einer Reise."], "_exampleTrans": {"en": "She rewards herself for the many overtime hours with a trip.", "tr": "Çok sayıdaki fazla mesai için kendini bir seyahatle ödüllendiriyor.", "ru": "За многочисленные сверхурочные часы она награждает себя поездкой.", "uk": "За численні понаднормові години вона винагороджує себе подорожжю.", "es": "Se recompensa por las muchas horas extra con un viaje.", "fa": "او برای اضافه‌کاری‌های زیادش خود را با یک سفر پاداش می‌دهد.", "ar": "تكافئ نفسها على ساعات العمل الإضافية الكثيرة برحلة."}}, {"id": "vap_ef4965667a6e", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich beschäftigen + mit", "cat": "vp", "syn": ["sich befassen", "arbeiten an", "behandeln", "sich widmen"], "ex": ["Sie beschäftigt sich mit dem neuen Investitionsplan."], "_exampleTrans": {"en": "She is dealing with the new investment plan.", "tr": "Yeni yatırım planıyla ilgileniyor.", "ru": "Она занимается новым инвестиционным планом.", "uk": "Вона займається новим інвестиційним планом.", "es": "Ella se ocupa del nuevo plan de inversión.", "fa": "او مشغول بررسی طرح سرمایه‌گذاری جدید است.", "ar": "إنها منشغلة بخطة الاستثمار الجديدة."}}, {"id": "vap_5add65f37875", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "besprechen + mit", "cat": "vp", "syn": ["erörtern", "diskutieren", "durchsprechen", "beraten"], "ex": ["Georg bespricht das Problem mit seiner Chefin."], "_exampleTrans": {"en": "Georg discusses the problem with his boss.", "tr": "Georg sorunu patronuyla görüşüyor.", "ru": "Георг обсуждает проблему со своей начальницей.", "uk": "Георг обговорює проблему зі своєю начальницею.", "es": "Georg habla del problema con su jefa.", "fa": "گئورگ مشکل را با رئیسش مطرح می‌کند.", "ar": "يناقش جورج المشكلة مع مديرته."}}, {"id": "vap_0b4911545734", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "konkurrieren + mit/um", "cat": "vp", "syn": ["wetteifern", "im Wettbewerb stehen", "rivalisieren", "konkurrieren"], "ex": ["Wir konkurrieren mit Produzenten aus dem Ausland."], "_exampleTrans": {"en": "We compete with producers from abroad.", "tr": "Yurt dışındaki üreticilerle rekabet ediyoruz.", "ru": "Мы конкурируем с производителями из-за рубежа.", "uk": "Ми конкуруємо з виробниками з-за кордону.", "es": "Competimos con productores del extranjero.", "fa": "ما با تولیدکنندگان خارجی رقابت می‌کنیم.", "ar": "نحن نتنافس مع منتجين من الخارج."}}, {"id": "vap_105c0520a32e", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "rechnen + mit", "cat": "vp", "syn": ["erwarten", "zählen auf", "kalkulieren", "rechnen"], "ex": ["Wir haben schon nicht mehr mit Ihnen gerechnet."], "_exampleTrans": {"en": "We were no longer expecting you.", "tr": "Artık sizi beklemiyorduk.", "ru": "Мы уже больше не рассчитывали на Вас.", "uk": "Ми вже більше не розраховували на Вас.", "es": "Ya no contábamos con usted.", "fa": "دیگر انتظار شما را نداشتیم.", "ar": "لم نعد نتوقع حضوركم."}}, {"id": "vap_fdffa431e796", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "reden + mit/über/von", "cat": "vp", "syn": ["sprechen", "sich unterhalten", "reden", "plaudern"], "ex": ["Herr Ohm redet mit der Chefin."], "_exampleTrans": {"en": "Mr. Ohm is talking with the boss.", "tr": "Bay Ohm patronla konuşuyor.", "ru": "Господин Ом разговаривает с начальницей.", "uk": "Пан Ом розмовляє з начальницею.", "es": "El señor Ohm habla con la jefa.", "fa": "آقای اهم با رئیس صحبت می‌کند.", "ar": "يتحدث السيد أوم مع المديرة."}}, {"id": "vap_12ca5d55531d", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "schimpfen + mit/über", "cat": "vp", "syn": ["meckern", "tadeln", "schimpfen", "sich beklagen"], "ex": ["Bitte schimpf nicht mit mir! Ich kann nichts dafür!"], "_exampleTrans": {"en": "Please don't scold me! I can't help it!", "tr": "Lütfen bana kızma! Benim suçum değil!", "ru": "Пожалуйста, не ругай меня! Я ничего не могу поделать!", "uk": "Будь ласка, не сваріть мене! Я тут ні до чого!", "es": "¡Por favor, no me regañes! ¡Yo no tengo la culpa!", "fa": "لطفاً مرا سرزنش نکن! من تقصیری ندارم!", "ar": "من فضلك لا توبّخني! لا ذنب لي في ذلك!"}}, {"id": "vap_43e426ac2e80", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sprechen + mit/über/von", "cat": "vp", "syn": ["reden", "kommunizieren", "sich äußern", "sprechen"], "ex": ["Mit wem sprechen Sie?"], "_exampleTrans": {"en": "With whom are you speaking?", "tr": "Kiminle konuşuyorsunuz?", "ru": "С кем Вы разговариваете?", "uk": "З ким Ви розмовляєте?", "es": "¿Con quién habla usted?", "fa": "با چه کسی صحبت می‌کنید؟", "ar": "مع من تتحدثون؟"}}, {"id": "vap_0e9870424509", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "(sich) streiten + mit/über", "cat": "vp", "syn": ["sich zanken", "diskutieren", "sich auseinandersetzen", "streiten"], "ex": ["Er streitet sich oft mit seinen Kollegen."], "_exampleTrans": {"en": "He often argues with his colleagues.", "tr": "Meslektaşlarıyla sık sık tartışır.", "ru": "Он часто ссорится со своими коллегами.", "uk": "Він часто свариться зі своїми колегами.", "es": "A menudo discute con sus colegas.", "fa": "او اغلب با همکارانش جر و بحث می‌کند.", "ar": "غالبًا ما يتشاجر مع زملائه."}}, {"id": "vap_dd9606f4aeeb", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "telefonieren + mit", "cat": "vp", "syn": ["anrufen", "sprechen", "telefonieren", "sich melden"], "ex": ["Fred telefoniert oft mit Marina."], "_exampleTrans": {"en": "Fred often talks on the phone with Marina.", "tr": "Fred sık sık Marina ile telefonda konuşur.", "ru": "Фред часто говорит по телефону с Мариной.", "uk": "Фред часто розмовляє телефоном з Мариною.", "es": "Fred habla a menudo por teléfono con Marina.", "fa": "فرد اغلب با مارینا تلفنی صحبت می‌کند.", "ar": "يتحدث فريد كثيرًا عبر الهاتف مع مارينا."}}, {"id": "vap_c140faa4851c", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich treffen + mit", "cat": "vp", "syn": ["sich begegnen", "zusammenkommen", "sich treffen", "verabreden"], "ex": ["Heute treffen wir uns mit guten Freunden."], "_exampleTrans": {"en": "Today we are meeting with good friends.", "tr": "Bugün iyi arkadaşlarla buluşuyoruz.", "ru": "Сегодня мы встречаемся с хорошими друзьями.", "uk": "Сьогодні ми зустрічаємося з добрими друзями.", "es": "Hoy nos reunimos con buenos amigos.", "fa": "امروز با دوستان خوبمان ملاقات می‌کنیم.", "ar": "نلتقي اليوم بأصدقاء جيدين."}}, {"id": "vap_51e317c455e5", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "verbinden + mit", "cat": "vp", "syn": ["verknüpfen", "koppeln", "verbinden", "anschließen"], "ex": ["Können Sie mich bitte mit dem Sekretariat verbinden?"], "_exampleTrans": {"en": "Could you please connect me with the secretariat?", "tr": "Beni lütfen sekreterliğe bağlayabilir misiniz?", "ru": "Не могли бы Вы соединить меня с секретариатом?", "uk": "Чи могли б Ви з’єднати мене із секретаріатом?", "es": "¿Podría comunicarme, por favor, con la secretaría?", "fa": "ممکن است لطفاً مرا به دبیرخانه وصل کنید؟", "ar": "هل يمكنكم من فضلكم توصيلي بالسكرتارية؟"}}, {"id": "vap_7f339a43ab62", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "vergleichen + mit", "cat": "vp", "syn": ["gegenüberstellen", "abgleichen", "vergleichen", "messen"], "ex": ["Vergleichen Sie Ihr Land mit Deutschland."], "_exampleTrans": {"en": "Compare your country with Germany.", "tr": "Ülkenizi Almanya ile karşılaştırın.", "ru": "Сравните свою страну с Германией.", "uk": "Порівняйте свою країну з Німеччиною.", "es": "Compare su país con Alemania.", "fa": "کشورتان را با آلمان مقایسه کنید.", "ar": "قارنوا بلدكم بألمانيا."}}, {"id": "vap_18aa0d5679c6", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich verstehen + mit", "cat": "vp", "syn": ["sich vertragen", "auskommen", "verstehen", "harmonieren"], "ex": ["Sie versteht sich gut mit ihm."], "_exampleTrans": {"en": "She gets along well with him.", "tr": "Onunla iyi anlaşıyor.", "ru": "Она хорошо с ним ладит.", "uk": "Вона добре з ним ладнає.", "es": "Ella se lleva bien con él.", "fa": "او با او خوب کنار می‌آید.", "ar": "إنها تتفاهم معه جيدًا."}}, {"id": "vap_2a9a1cffb236", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "zusammenarbeiten + mit", "cat": "vp", "syn": ["kooperieren", "kollaborieren", "mitarbeiten", "zusammenwirken"], "ex": ["Er arbeitet mit Ärzten und Pflegern zusammen."], "_exampleTrans": {"en": "He works together with doctors and nurses.", "tr": "Doktorlar ve hemşirelerle birlikte çalışıyor.", "ru": "Он сотрудничает с врачами и медсёстрами.", "uk": "Він співпрацює з лікарями та медсестрами.", "es": "Trabaja con médicos y enfermeros.", "fa": "او با پزشکان و پرستاران همکاری می‌کند.", "ar": "يعمل مع الأطباء والممرضين."}}, {"id": "vap_17a4d3109d22", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "fragen + nach", "cat": "vp", "syn": ["sich erkundigen", "nachfragen", "anfragen", "fragen"], "ex": ["Yvonne hat mich nach meinen Plänen für die Zukunft gefragt."], "_exampleTrans": {"en": "Yvonne asked me about my plans for the future.", "tr": "Yvonne bana gelecek planlarımı sordu.", "ru": "Ивонна спросила меня о моих планах на будущее.", "uk": "Івонна запитала мене про мої плани на майбутнє.", "es": "Yvonne me preguntó por mis planes para el futuro.", "fa": "ایوون از من دربارهٔ برنامه‌هایم برای آینده پرسید.", "ar": "سألتني إيفون عن خططي للمستقبل."}}, {"id": "vap_db21534c4d74", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "riechen + nach", "cat": "vp", "syn": ["duften", "stinken", "riechen", "Geruch haben"], "ex": ["Hier riecht es nach Farbe."], "_exampleTrans": {"en": "It smells like paint here.", "tr": "Burası boya kokuyor.", "ru": "Здесь пахнет краской.", "uk": "Тут пахне фарбою.", "es": "Aquí huele a pintura.", "fa": "اینجا بوی رنگ می‌دهد.", "ar": "هنا رائحة طلاء."}}, {"id": "vap_ff0341ac09a8", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "rufen + nach", "cat": "vp", "syn": ["schreien", "nennen", "herbeirufen", "rufen"], "ex": ["Er rief nach dem Kellner, aber der kam nicht."], "_exampleTrans": {"en": "He called for the waiter, but he did not come.", "tr": "Garsonu çağırdı, ama o gelmedi.", "ru": "Он позвал официанта, но тот не пришёл.", "uk": "Він покликав офіціанта, але той не прийшов.", "es": "Llamó al camarero, pero este no vino.", "fa": "او پیشخدمت را صدا زد، اما او نیامد.", "ar": "نادى النادل، لكنه لم يأتِ."}}, {"id": "vap_45bfb59c2406", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "schmecken + nach", "cat": "vp", "syn": ["munden", "schmecken", "einen Geschmack haben", "kosten"], "ex": ["Dieses Eis schmeckt nach Apfel."], "_exampleTrans": {"en": "This ice cream tastes like apple.", "tr": "Bu dondurmanın tadı elma gibi.", "ru": "Это мороженое имеет вкус яблока.", "uk": "Це морозиво має смак яблука.", "es": "Este helado sabe a manzana.", "fa": "این بستنی طعم سیب می‌دهد.", "ar": "طعم هذا الآيس كريم يشبه التفاح."}}, {"id": "vap_f09fa5ee8847", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sehen + nach", "cat": "vp", "syn": ["nachsehen", "prüfen", "schauen", "sich kümmern"], "ex": ["Ich sehe mal schnell nach der noch fehlenden Kollegin."], "_exampleTrans": {"en": "I will quickly check on the still-missing colleague.", "tr": "Hâlâ gelmemiş olan meslektaşa hızlıca bakayım.", "ru": "Я быстро посмотрю, что с ещё отсутствующей коллегой.", "uk": "Я швидко перевірю ще відсутню колегу.", "es": "Voy a ver rápidamente qué pasa con la colega que aún falta.", "fa": "سریع به همکار هنوز غایب سر می‌زنم.", "ar": "سألقي نظرة سريعة على الزميلة التي ما زالت غائبة."}}, {"id": "vap_35269a6b738a", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich ärgern + über", "cat": "vp", "syn": ["sich ärgern", "sich aufregen", "verärgert sein", "sich empören"], "ex": ["Ich ärgere mich über intolerante Menschen."], "_exampleTrans": {"en": "I am annoyed about intolerant people.", "tr": "Hoşgörüsüz insanlara kızıyorum.", "ru": "Меня раздражают нетерпимые люди.", "uk": "Мене дратують нетолерантні люди.", "es": "Me molestan las personas intolerantes.", "fa": "از آدم‌های بی‌تحمل عصبانی می‌شوم.", "ar": "أنزعج من الأشخاص غير المتسامحين."}}, {"id": "vap_52ea1f1d8c78", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich austauschen + über/mit", "cat": "vp", "syn": ["kommunizieren", "sich besprechen", "Erfahrungen teilen", "sich beraten"], "ex": ["Die Kollegen tauschten sich über ihre Erfahrungen aus."], "_exampleTrans": {"en": "The colleagues exchanged views about their experiences.", "tr": "Meslektaşlar deneyimleri hakkında fikir alışverişinde bulundu.", "ru": "Коллеги обменялись мнениями о своём опыте.", "uk": "Колеги обмінялися думками про свій досвід.", "es": "Los colegas intercambiaron opiniones sobre sus experiencias.", "fa": "همکاران دربارهٔ تجربه‌هایشان تبادل نظر کردند.", "ar": "تبادل الزملاء الآراء حول تجاربهم."}}, {"id": "vap_05fa7aeb8860", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich beklagen + über", "cat": "vp", "syn": ["klagen", "sich beschweren", "bemängeln", "monieren"], "ex": ["Sie hat sich über die schlechte Zusammenarbeit beklagt."], "_exampleTrans": {"en": "She complained about the poor cooperation.", "tr": "Kötü iş birliğinden şikâyet etti.", "ru": "Она пожаловалась на плохое сотрудничество.", "uk": "Вона поскаржилася на погану співпрацю.", "es": "Se quejó de la mala colaboración.", "fa": "او از همکاری بد شکایت کرد.", "ar": "اشتكت من سوء التعاون."}}, {"id": "vap_0189ca3926ed", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "belehren + über", "cat": "vp", "syn": ["unterweisen", "informieren", "aufklären", "instruieren"], "ex": ["Er wurde über seine Pflichten belehrt."], "_exampleTrans": {"en": "He was instructed about his duties.", "tr": "Görevleri konusunda bilgilendirildi.", "ru": "Его проинструктировали о его обязанностях.", "uk": "Його поінформували про його обов’язки.", "es": "Se le informó sobre sus obligaciones.", "fa": "او دربارهٔ وظایفش آگاه شد.", "ar": "تم إبلاغه بواجباته."}}, {"id": "vap_3a42e425af18", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "beraten + über", "cat": "vp", "syn": ["besprechen", "konsultieren", "sich abstimmen", "erörtern"], "ex": ["Wir müssen uns über den Plan noch beraten."], "_exampleTrans": {"en": "We still have to deliberate on the plan.", "tr": "Plan üzerinde hâlâ görüşmemiz gerekiyor.", "ru": "Нам ещё нужно обсудить план.", "uk": "Нам ще потрібно обговорити план.", "es": "Todavía tenemos que deliberar sobre el plan.", "fa": "ما هنوز باید دربارهٔ طرح مشورت کنیم.", "ar": "لا يزال علينا التشاور بشأن الخطة."}}, {"id": "vap_c907d2955dce", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "berichten + über", "cat": "vp", "syn": ["melden", "mitteilen", "referieren", "darstellen"], "ex": ["Er hat über den Projektverlauf berichtet."], "_exampleTrans": {"en": "He reported on the course of the project.", "tr": "Projenin gidişatı hakkında rapor verdi.", "ru": "Он сообщил о ходе проекта.", "uk": "Він повідомив про перебіг проєкту.", "es": "Informó sobre el desarrollo del proyecto.", "fa": "او دربارهٔ روند پروژه گزارش داد.", "ar": "قدّم تقريرًا عن سير المشروع."}}, {"id": "vap_9ab38863d51b", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich beschweren + über", "cat": "vp", "syn": ["klagen", "reklamieren", "monieren", "protestieren"], "ex": ["Er beschwerte sich über seine schlechte Beurteilung."], "_exampleTrans": {"en": "He complained about his poor evaluation.", "tr": "Kötü değerlendirmesinden şikâyet etti.", "ru": "Он пожаловался на свою плохую оценку.", "uk": "Він поскаржився на свою погану оцінку.", "es": "Se quejó de su mala evaluación.", "fa": "او از ارزیابی بدش شکایت کرد.", "ar": "اشتكى من تقييمه السيئ."}}, {"id": "vap_e55261a449ec", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "brüten + über", "cat": "vp", "syn": ["grübeln", "nachdenken", "tüfteln", "sich den Kopf zerbrechen"], "ex": ["Sie brütet seit Wochen über dem Bericht."], "_exampleTrans": {"en": "She has been brooding over the report for weeks.", "tr": "Haftalardır rapor üzerinde kafa yoruyor.", "ru": "Она уже несколько недель ломает голову над отчётом.", "uk": "Вона вже тижнями сушить голову над звітом.", "es": "Lleva semanas dándole vueltas al informe.", "fa": "هفته‌هاست روی گزارش فکر می‌کند.", "ar": "إنها تفكر مليًا في التقرير منذ أسابيع."}}, {"id": "vap_b668eb3f19ed", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "diskutieren + über", "cat": "vp", "syn": ["erörtern", "debattieren", "besprechen", "diskutieren"], "ex": ["Sie diskutieren immer über dasselbe Problem."], "_exampleTrans": {"en": "They are always discussing the same problem.", "tr": "Hep aynı sorunu tartışıyorlar.", "ru": "Они всё время обсуждают одну и ту же проблему.", "uk": "Вони постійно обговорюють одну й ту саму проблему.", "es": "Siempre discuten sobre el mismo problema.", "fa": "آن‌ها همیشه دربارهٔ همان مشکل بحث می‌کنند.", "ar": "إنهم يناقشون دائمًا المشكلة نفسها."}}, {"id": "vap_e7391d51d8e7", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich freuen + über/auf", "cat": "vp", "syn": ["sich freuen", "sich begeistern", "glücklich sein", "erfreut sein"], "ex": ["Fredo freut sich über jeden Sieg vom 1. FC Köln."], "_exampleTrans": {"en": "Fredo is happy about every victory by 1. FC Cologne.", "tr": "Fredo, 1. FC Köln’ün her galibiyetine seviniyor.", "ru": "Фредо радуется каждой победе «1. FC Köln».", "uk": "Фредо радіє кожній перемозі «1. FC Köln».", "es": "Fredo se alegra de cada victoria del 1. FC Köln.", "fa": "فردو از هر پیروزی تیم 1. FC Köln خوشحال می‌شود.", "ar": "يفرح فريدو بكل فوز لفريق 1. FC Köln."}}, {"id": "vap_6c0ed3505784", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "hinauskommen + über", "cat": "vp", "syn": ["überschreiten", "hinausgehen", "übersteigen", "hinausreichen"], "ex": ["Die Partei ist nicht über 20 % hinausgekommen."], "_exampleTrans": {"en": "The party did not get beyond 20%.", "tr": "Parti yüzde 20’nin üzerine çıkamadı.", "ru": "Партия не превысила 20 %.", "uk": "Партія не перевищила 20 %.", "es": "El partido no superó el 20 %.", "fa": "حزب از ۲۰٪ فراتر نرفت.", "ar": "لم يتجاوز الحزب نسبة 20٪."}}, {"id": "vap_813a3401ce45", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich informieren + über", "cat": "vp", "syn": ["sich erkundigen", "nachlesen", "Informationen einholen", "sich kundig machen"], "ex": ["Ich lese Zeitung, um mich über die Politik zu informieren."], "_exampleTrans": {"en": "I read the newspaper in order to inform myself about politics.", "tr": "Siyaset hakkında bilgi edinmek için gazete okuyorum.", "ru": "Я читаю газету, чтобы информироваться о политике.", "uk": "Я читаю газету, щоб дізнаватися про політику.", "es": "Leo el periódico para informarme sobre política.", "fa": "من روزنامه می‌خوانم تا دربارهٔ سیاست آگاه شوم.", "ar": "أقرأ الصحيفة كي أطلع على السياسة."}}, {"id": "vap_7a6ec8b8d109", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "lächeln + über", "cat": "vp", "syn": ["schmunzeln", "freundlich blicken", "lächeln", "milde reagieren"], "ex": ["Über die neue Kollegin kann sie nur lächeln."], "_exampleTrans": {"en": "She can only smile about the new colleague.", "tr": "Yeni meslektaşa sadece gülümseyebilir.", "ru": "О новой коллеге она может только улыбнуться.", "uk": "Про нову колегу вона може лише усміхнутися.", "es": "Ella solo puede sonreír ante la nueva colega.", "fa": "او دربارهٔ همکار جدید فقط می‌تواند لبخند بزند.", "ar": "لا يسعها إلا أن تبتسم بخصوص الزميلة الجديدة."}}, {"id": "vap_5cc59dc69a37", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "lachen + über", "cat": "vp", "syn": ["kichern", "schmunzeln", "sich amüsieren", "lachen"], "ex": ["Sie konnte über den Witz nicht lachen."], "_exampleTrans": {"en": "She could not laugh at the joke.", "tr": "Fıkraya gülemedi.", "ru": "Она не смогла посмеяться над шуткой.", "uk": "Вона не змогла посміятися з жарту.", "es": "No pudo reírse del chiste.", "fa": "او نتوانست به آن شوخی بخندد.", "ar": "لم تستطع أن تضحك على النكتة."}}, {"id": "vap_f42ffa38d0f1", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "nachdenken + über", "cat": "vp", "syn": ["überlegen", "reflektieren", "grübeln", "erwägen"], "ex": ["Ich habe lange über den Vorschlag nachgedacht."], "_exampleTrans": {"en": "I thought about the proposal for a long time.", "tr": "Öneri üzerine uzun uzun düşündüm.", "ru": "Я долго думал над предложением.", "uk": "Я довго думав над пропозицією.", "es": "Pensé mucho sobre la propuesta.", "fa": "من مدت زیادی دربارهٔ پیشنهاد فکر کردم.", "ar": "فكرت طويلًا في الاقتراح."}}, {"id": "vap_f272be54bb3d", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "reden + über/mit/von", "cat": "vp", "syn": ["sprechen", "sich unterhalten", "reden", "plaudern"], "ex": ["Wir haben über den Chef geredet."], "_exampleTrans": {"en": "We talked about the boss.", "tr": "Patron hakkında konuştuk.", "ru": "Мы говорили о начальнике.", "uk": "Ми говорили про начальника.", "es": "Hablamos sobre el jefe.", "fa": "ما دربارهٔ رئیس صحبت کردیم.", "ar": "تحدثنا عن المدير."}}, {"id": "vap_395801390356", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "referieren + über", "cat": "vp", "syn": ["vortragen", "berichten", "präsentieren", "referieren"], "ex": ["Sie referierte über den neuen Werbeplan."], "_exampleTrans": {"en": "She gave a presentation on the new advertising plan.", "tr": "Yeni reklam planı hakkında sunum yaptı.", "ru": "Она выступила с докладом о новом рекламном плане.", "uk": "Вона зробила доповідь про новий рекламний план.", "es": "Ella dio una exposición sobre el nuevo plan publicitario.", "fa": "او دربارهٔ طرح تبلیغاتی جدید سخنرانی کرد.", "ar": "قدّمت عرضًا عن خطة الإعلان الجديدة."}}, {"id": "vap_06b0d77d4388", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "schimpfen + über/mit", "cat": "vp", "syn": ["meckern", "tadeln", "schimpfen", "sich beklagen"], "ex": ["Sie schimpfte über den Lärm."], "_exampleTrans": {"en": "She complained about the noise.", "tr": "Gürültüden şikâyet etti.", "ru": "Она ругалась из-за шума.", "uk": "Вона сварилася через шум.", "es": "Se quejó del ruido.", "fa": "او از سروصدا شکایت کرد.", "ar": "تذمرت من الضجيج."}}, {"id": "vap_d26cd44e22da", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sprechen + über/mit/von", "cat": "vp", "syn": ["reden", "kommunizieren", "sich äußern", "sprechen"], "ex": ["Ich spreche fast nie über Politik."], "_exampleTrans": {"en": "I almost never talk about politics.", "tr": "Neredeyse hiç siyaset hakkında konuşmam.", "ru": "Я почти никогда не говорю о политике.", "uk": "Я майже ніколи не говорю про політику.", "es": "Casi nunca hablo de política.", "fa": "من تقریباً هرگز دربارهٔ سیاست صحبت نمی‌کنم.", "ar": "لا أتحدث تقريبًا أبدًا عن السياسة."}}, {"id": "vap_121b2e93c55c", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "(sich) streiten + über/mit", "cat": "vp", "syn": ["sich zanken", "diskutieren", "sich auseinandersetzen", "streiten"], "ex": ["Wir streiten im Team oft über Kleinigkeiten."], "_exampleTrans": {"en": "In the team, we often argue about trivial matters.", "tr": "Takımda sık sık önemsiz şeyler yüzünden tartışırız.", "ru": "В команде мы часто спорим из-за мелочей.", "uk": "У команді ми часто сперечаємося через дрібниці.", "es": "En el equipo discutimos a menudo sobre pequeñeces.", "fa": "ما در تیم اغلب دربارهٔ چیزهای جزئی بحث می‌کنیم.", "ar": "في الفريق نتجادل كثيرًا حول أمور صغيرة."}}, {"id": "vap_b15fa37e4012", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "verfügen + über", "cat": "vp", "syn": ["besitzen", "haben", "verfügen", "zur Verfügung haben"], "ex": ["Am Jahresende verfügte die Firma über 20 Mio. Euro Gewinn."], "_exampleTrans": {"en": "At the end of the year, the company had 20 million euros in profit.", "tr": "Yıl sonunda şirketin 20 milyon avro kârı vardı.", "ru": "В конце года фирма располагала прибылью в 20 млн евро.", "uk": "Наприкінці року фірма мала прибуток у 20 млн євро.", "es": "A final de año, la empresa disponía de 20 millones de euros de beneficio.", "fa": "در پایان سال، شرکت ۲۰ میلیون یورو سود در اختیار داشت.", "ar": "في نهاية العام كانت الشركة تملك ربحًا قدره 20 مليون يورو."}}, {"id": "vap_9bb84ced142b", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich wundern + über", "cat": "vp", "syn": ["sich wundern", "erstaunt sein", "überrascht sein", "staunen"], "ex": ["Sie wunderten sich nicht über seine guten Leistungen."], "_exampleTrans": {"en": "They were not surprised by his good performance.", "tr": "Onun iyi performansına şaşırmadılar.", "ru": "Они не удивились его хорошим результатам.", "uk": "Вони не здивувалися його добрим результатам.", "es": "No se sorprendieron de sus buenos resultados.", "fa": "آن‌ها از عملکرد خوب او تعجب نکردند.", "ar": "لم يتعجبوا من أدائه الجيد."}}, {"id": "vap_1c1203731344", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich bemühen + um", "cat": "vp", "syn": ["sich anstrengen", "sich einsetzen", "sich kümmern", "versuchen"], "ex": ["Sie hat sich um einen neuen Job bemüht."], "_exampleTrans": {"en": "She made an effort to get a new job.", "tr": "Yeni bir iş bulmak için çaba gösterdi.", "ru": "Она постаралась найти новую работу.", "uk": "Вона доклала зусиль, щоб знайти нову роботу.", "es": "Ella se esforzó por conseguir un nuevo empleo.", "fa": "او برای به‌دست آوردن شغلی جدید تلاش کرد.", "ar": "بذلت جهدًا للحصول على وظيفة جديدة."}}, {"id": "vap_760db379b112", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich bewerben + um", "cat": "vp", "syn": ["sich bewerben", "sich bemühen", "kandidieren", "sich melden"], "ex": ["Ich habe mich um einen neuen Job beworben."], "_exampleTrans": {"en": "I applied for a new job.", "tr": "Yeni bir işe başvurdum.", "ru": "Я подал заявление на новую работу.", "uk": "Я подав заявку на нову роботу.", "es": "Solicité un nuevo empleo.", "fa": "من برای یک شغل جدید درخواست دادم.", "ar": "تقدمت بطلب للحصول على وظيفة جديدة."}}, {"id": "vap_d242de4cb107", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "bitten + um", "cat": "vp", "syn": ["ersuchen", "anfragen", "bitten", "ersuchen"], "ex": ["Sophie bittet ihre Freundin um einen Tipp."], "_exampleTrans": {"en": "Sophie asks her friend for a tip.", "tr": "Sophie arkadaşından bir tavsiye istiyor.", "ru": "Софи просит у своей подруги совета.", "uk": "Софі просить у своєї подруги поради.", "es": "Sophie le pide un consejo a su amiga.", "fa": "سوفی از دوستش یک راهنمایی می‌خواهد.", "ar": "تطلب صوفي من صديقتها نصيحة."}}, {"id": "vap_7b80b66afdef", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "gehen + um", "cat": "vp", "syn": ["sich drehen", "handeln", "betreffen", "zum Thema haben"], "ex": ["In dem Bericht geht es um die Marketingaktivitäten."], "_exampleTrans": {"en": "The report is about the marketing activities.", "tr": "Raporda pazarlama faaliyetleri ele alınıyor.", "ru": "В отчёте речь идёт о маркетинговых мероприятиях.", "uk": "У звіті йдеться про маркетингову діяльність.", "es": "El informe trata de las actividades de marketing.", "fa": "گزارش دربارهٔ فعالیت‌های بازاریابی است.", "ar": "يتناول التقرير أنشطة التسويق."}}, {"id": "vap_cc063f39b181", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "handeln + um/von", "cat": "vp", "syn": ["sich drehen", "thematisieren", "betreffen", "behandeln"], "ex": ["Ich möchte Sie sprechen. Es handelt sich um den Bericht."], "_exampleTrans": {"en": "I would like to speak with you. It is about the report.", "tr": "Sizinle konuşmak istiyorum. Konu rapor.", "ru": "Я хотел бы поговорить с Вами. Речь идёт об отчёте.", "uk": "Я хотів би поговорити з Вами. Йдеться про звіт.", "es": "Quisiera hablar con usted. Se trata del informe.", "fa": "می‌خواهم با شما صحبت کنم. موضوع گزارش است.", "ar": "أود أن أتحدث معكم. الأمر يتعلق بالتقرير."}}, {"id": "vap_ce781a54bf30", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "konkurrieren + um/mit", "cat": "vp", "syn": ["wetteifern", "im Wettbewerb stehen", "rivalisieren", "konkurrieren"], "ex": ["Viele Firmen konkurrieren um Marktanteile."], "_exampleTrans": {"en": "Many companies compete for market shares.", "tr": "Birçok firma pazar payları için rekabet ediyor.", "ru": "Многие фирмы конкурируют за доли рынка.", "uk": "Багато фірм конкурують за частки ринку.", "es": "Muchas empresas compiten por cuotas de mercado.", "fa": "بسیاری از شرکت‌ها برای سهم بازار رقابت می‌کنند.", "ar": "تتنافس شركات كثيرة على حصص السوق."}}, {"id": "vap_3055cd4576b6", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich kümmern + um", "cat": "vp", "syn": ["sich kümmern", "betreuen", "sorgen", "sich annehmen"], "ex": ["In vielen Familien kümmern sich die Frauen um den Haushalt."], "_exampleTrans": {"en": "In many families, the women take care of the household.", "tr": "Birçok ailede ev işleriyle kadınlar ilgilenir.", "ru": "Во многих семьях женщины заботятся о домашнем хозяйстве.", "uk": "У багатьох сім’ях жінки дбають про домашнє господарство.", "es": "En muchas familias, las mujeres se ocupan del hogar.", "fa": "در بسیاری از خانواده‌ها زنان به امور خانه رسیدگی می‌کنند.", "ar": "في كثير من العائلات تهتم النساء بشؤون المنزل."}}, {"id": "vap_7f5ee3a001e0", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "leiden + unter", "cat": "vp", "syn": ["ertragen", "beeinträchtigt sein", "leiden", "Schmerzen haben"], "ex": ["Unter dem hohen Energieverbrauch leidet auch die Umwelt."], "_exampleTrans": {"en": "The environment also suffers from the high energy consumption.", "tr": "Yüksek enerji tüketiminden çevre de zarar görüyor.", "ru": "От высокого потребления энергии страдает и окружающая среда.", "uk": "Від високого споживання енергії страждає також довкілля.", "es": "El medio ambiente también sufre por el alto consumo de energía.", "fa": "محیط زیست نیز از مصرف بالای انرژی آسیب می‌بیند.", "ar": "تعاني البيئة أيضًا من ارتفاع استهلاك الطاقة."}}, {"id": "vap_0fa6a5568468", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "abweichen + von", "cat": "vp", "syn": ["abweichen", "abgehen", "sich unterscheiden", "divergieren"], "ex": ["Bitte weichen Sie nicht vom Thema ab."], "_exampleTrans": {"en": "Please do not deviate from the topic.", "tr": "Lütfen konudan sapmayın.", "ru": "Пожалуйста, не отклоняйтесь от темы.", "uk": "Будь ласка, не відхиляйтеся від теми.", "es": "Por favor, no se desvíe del tema.", "fa": "لطفاً از موضوع منحرف نشوید.", "ar": "من فضلكم لا تخرجوا عن الموضوع."}}, {"id": "vap_1be726a05e36", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "berichten + von", "cat": "vp", "syn": ["melden", "mitteilen", "referieren", "darstellen"], "ex": ["Der Kollege berichtet von seiner letzten Dienstreise nach Wien."], "_exampleTrans": {"en": "The colleague reports about his last business trip to Vienna.", "tr": "Meslektaş, Viyana’ya yaptığı son iş seyahatinden bahsediyor.", "ru": "Коллега рассказывает о своей последней командировке в Вену.", "uk": "Колега розповідає про своє останнє відрядження до Відня.", "es": "El colega informa sobre su último viaje de negocios a Viena.", "fa": "همکار از آخرین سفر کاری‌اش به وین گزارش می‌دهد.", "ar": "يتحدث الزميل عن آخر رحلة عمل له إلى فيينا."}}, {"id": "vap_f0c165b73ed1", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich entfernen + von", "cat": "vp", "syn": ["weggehen", "sich distanzieren", "abrücken", "sich entfernen"], "ex": ["Er entfernte sich vom Tatort."], "_exampleTrans": {"en": "He moved away from the crime scene.", "tr": "Suç mahallinden uzaklaştı.", "ru": "Он удалился с места преступления.", "uk": "Він віддалився від місця злочину.", "es": "Se alejó del lugar del delito.", "fa": "او از محل جرم دور شد.", "ar": "ابتعد عن مسرح الجريمة."}}, {"id": "vap_03e3e0bc26d7", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich erholen + von", "cat": "vp", "syn": ["genesen", "sich erholen", "regenerieren", "wieder zu Kräften kommen"], "ex": ["Sie hat sich gut von dem Unfall erholt."], "_exampleTrans": {"en": "She recovered well from the accident.", "tr": "Kazadan sonra iyi toparlandı.", "ru": "Она хорошо оправилась после аварии.", "uk": "Вона добре оговталася після нещасного випадку.", "es": "Se recuperó bien del accidente.", "fa": "او به‌خوبی از حادثه بهبود یافت.", "ar": "تعافت جيدًا من الحادث."}}, {"id": "vap_d70fd7ff168c", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich erstrecken + von/bis", "cat": "vp", "syn": ["sich ausdehnen", "reichen", "verlaufen", "sich hinziehen"], "ex": ["Die Alpen erstrecken sich von Frankreich bis (nach) Slowenien."], "_exampleTrans": {"en": "The Alps extend from France to Slovenia.", "tr": "Alpler Fransa’dan Slovenya’ya kadar uzanır.", "ru": "Альпы простираются от Франции до Словении.", "uk": "Альпи простягаються від Франції до Словенії.", "es": "Los Alpes se extienden desde Francia hasta Eslovenia.", "fa": "کوه‌های آلپ از فرانسه تا اسلوونی امتداد دارند.", "ar": "تمتد جبال الألب من فرنسا إلى سلوفينيا."}}, {"id": "vap_c6a6c841c4bb", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "erzählen + von", "cat": "vp", "syn": ["berichten", "schildern", "mitteilen", "erzählen"], "ex": ["Eine Wissenschaftlerin hat mir von ihrem Beruf erzählt."], "_exampleTrans": {"en": "A scientist told me about her profession.", "tr": "Bir bilim kadını bana mesleğinden bahsetti.", "ru": "Одна учёная рассказала мне о своей профессии.", "uk": "Одна науковиця розповіла мені про свою професію.", "es": "Una científica me contó sobre su profesión.", "fa": "یک دانشمند زن از حرفه‌اش برایم تعریف کرد.", "ar": "حدّثتني عالمة عن مهنتها."}}, {"id": "vap_e985ea4fcf80", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "halten + von/für", "cat": "vp", "syn": ["meinen", "betrachten", "ansehen", "einschätzen"], "ex": ["Was halten Sie von der Idee?"], "_exampleTrans": {"en": "What do you think of the idea?", "tr": "Bu fikir hakkında ne düşünüyorsunuz?", "ru": "Что Вы думаете об этой идее?", "uk": "Що Ви думаєте про цю ідею?", "es": "¿Qué le parece la idea?", "fa": "نظر شما دربارهٔ این ایده چیست؟", "ar": "ما رأيكم في الفكرة؟"}}, {"id": "vap_11b111fe3c21", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "handeln + von/um", "cat": "vp", "syn": ["sich drehen", "thematisieren", "betreffen", "behandeln"], "ex": ["Der Film handelt von einem Migranten in Deutschland."], "_exampleTrans": {"en": "The film is about a migrant in Germany.", "tr": "Film Almanya’daki bir göçmen hakkındadır.", "ru": "Фильм рассказывает о мигранте в Германии.", "uk": "Фільм розповідає про мігранта в Німеччині.", "es": "La película trata de un migrante en Alemania.", "fa": "فیلم دربارهٔ یک مهاجر در آلمان است.", "ar": "يتناول الفيلم مهاجرًا في ألمانيا."}}, {"id": "vap_ee1dbadc0ecd", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "hören + von", "cat": "vp", "syn": ["erfahren", "vernehmen", "mitbekommen", "hören"], "ex": ["Ich habe schon viel von Ihnen gehört."], "_exampleTrans": {"en": "I have already heard a lot about you.", "tr": "Sizin hakkınızda şimdiden çok şey duydum.", "ru": "Я уже много слышал о Вас.", "uk": "Я вже багато чув про Вас.", "es": "Ya he oído mucho de usted.", "fa": "من تاکنون چیزهای زیادی دربارهٔ شما شنیده‌ام.", "ar": "لقد سمعت الكثير عنكم بالفعل."}}, {"id": "vap_84e3ace7b80f", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich losreißen + von", "cat": "vp", "syn": ["sich lösen", "sich losmachen", "sich befreien", "sich abwenden"], "ex": ["Ich konnte mich von der Arbeit nicht losreißen."], "_exampleTrans": {"en": "I could not tear myself away from work.", "tr": "Kendimi işten koparamadım.", "ru": "Я не мог оторваться от работы.", "uk": "Я не міг відірватися від роботи.", "es": "No pude despegarme del trabajo.", "fa": "نتوانستم خودم را از کار جدا کنم.", "ar": "لم أستطع أن أنفصل عن العمل."}}, {"id": "vap_2cf87b1229eb", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "profitieren + von", "cat": "vp", "syn": ["Nutzen ziehen", "gewinnen", "profitieren", "Vorteile haben"], "ex": ["Wir alle haben von ihren Ideen profitiert."], "_exampleTrans": {"en": "We all benefited from her ideas.", "tr": "Hepimiz onun fikirlerinden yararlandık.", "ru": "Мы все извлекли пользу из её идей.", "uk": "Ми всі скористалися її ідеями.", "es": "Todos nos beneficiamos de sus ideas.", "fa": "همهٔ ما از ایده‌های او بهره بردیم.", "ar": "استفدنا جميعًا من أفكارها."}}, {"id": "vap_5463449f3904", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "reden + von/mit/über", "cat": "vp", "syn": ["sprechen", "sich unterhalten", "reden", "plaudern"], "ex": ["Alle reden nur noch von diesem Film."], "_exampleTrans": {"en": "Everyone is still talking only about this film.", "tr": "Herkes hâlâ sadece bu filmden bahsediyor.", "ru": "Все до сих пор говорят только об этом фильме.", "uk": "Усі й досі говорять лише про цей фільм.", "es": "Todos siguen hablando solo de esta película.", "fa": "همه هنوز فقط دربارهٔ این فیلم صحبت می‌کنند.", "ar": "ما زال الجميع يتحدثون فقط عن هذا الفيلم."}}, {"id": "vap_616c7026a71b", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "schwärmen + von", "cat": "vp", "syn": ["begeistert erzählen", "loben", "schwärmen", "sich begeistern"], "ex": ["Sie schwärmen von ihrem letzten Urlaub."], "_exampleTrans": {"en": "They rave about their last holiday.", "tr": "Son tatillerinden büyük bir coşkuyla bahsediyorlar.", "ru": "Они восторженно рассказывают о своём последнем отпуске.", "uk": "Вони захоплено розповідають про свою останню відпустку.", "es": "Hablan con entusiasmo de sus últimas vacaciones.", "fa": "آن‌ها با شور و شوق از آخرین تعطیلاتشان تعریف می‌کنند.", "ar": "يتحدثون بحماس عن عطلتهم الأخيرة."}}, {"id": "vap_9aaeb2a1f6ac", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sprechen + von/mit/über", "cat": "vp", "syn": ["reden", "kommunizieren", "sich äußern", "sprechen"], "ex": ["In der Mittagspause sprachen alle vom Wetter."], "_exampleTrans": {"en": "During the lunch break, everyone talked about the weather.", "tr": "Öğle molasında herkes hava durumundan bahsetti.", "ru": "Во время обеденного перерыва все говорили о погоде.", "uk": "Під час обідньої перерви всі говорили про погоду.", "es": "Durante la pausa del mediodía, todos hablaron del tiempo.", "fa": "در وقت ناهار همه دربارهٔ هوا صحبت کردند.", "ar": "أثناء استراحة الغداء تحدث الجميع عن الطقس."}}, {"id": "vap_bedf776b18ab", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "träumen + von", "cat": "vp", "syn": ["sich wünschen", "fantasieren", "träumen", "hoffen"], "ex": ["Ich träume von der Zukunft."], "_exampleTrans": {"en": "I dream of the future.", "tr": "Geleceğin hayalini kuruyorum.", "ru": "Я мечтаю о будущем.", "uk": "Я мрію про майбутнє.", "es": "Sueño con el futuro.", "fa": "من رؤیای آینده را در سر دارم.", "ar": "أحلم بالمستقبل."}}, {"id": "vap_3530adc84c81", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich trennen + von", "cat": "vp", "syn": ["sich lösen", "scheiden", "auseinandergehen", "trennen"], "ex": ["Wir sollten uns von diesem Mitarbeiter trennen."], "_exampleTrans": {"en": "We should part with this employee.", "tr": "Bu çalışandan ayrılmalıyız.", "ru": "Нам следует расстаться с этим сотрудником.", "uk": "Нам слід розстатися з цим працівником.", "es": "Deberíamos separarnos de este empleado.", "fa": "ما باید از این کارمند جدا شویم.", "ar": "ينبغي أن ننفصل عن هذا الموظف."}}, {"id": "vap_ae3bbe06d535", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich unterscheiden + von", "cat": "vp", "syn": ["abweichen", "differieren", "sich unterscheiden", "anders sein"], "ex": ["Die neue Chefin unterscheidet sich stark von dem alten Chef."], "_exampleTrans": {"en": "The new boss differs greatly from the old boss.", "tr": "Yeni patron eski patrondan oldukça farklıdır.", "ru": "Новая начальница сильно отличается от старого начальника.", "uk": "Нова начальниця сильно відрізняється від старого начальника.", "es": "La nueva jefa se diferencia mucho del antiguo jefe.", "fa": "رئیس جدید تفاوت زیادی با رئیس قدیمی دارد.", "ar": "تختلف المديرة الجديدة كثيرًا عن المدير القديم."}}, {"id": "vap_6831329cd6a5", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich verabschieden + von", "cat": "vp", "syn": ["Abschied nehmen", "sich verabschieden", "Lebewohl sagen", "weggehen"], "ex": ["So, jetzt muss ich mich von Ihnen verabschieden."], "_exampleTrans": {"en": "Well, now I have to say goodbye to you.", "tr": "Peki, şimdi size veda etmem gerekiyor.", "ru": "Ну, теперь мне нужно с Вами попрощаться.", "uk": "Ну що ж, тепер мені треба з Вами попрощатися.", "es": "Bueno, ahora tengo que despedirme de usted.", "fa": "خب، حالا باید با شما خداحافظی کنم.", "ar": "حسنًا، الآن يجب أن أودّعكم."}}, {"id": "vap_1f6447c22a82", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "wissen + von", "cat": "vp", "syn": ["Kenntnis haben", "wissen", "informiert sein", "Bescheid wissen"], "ex": ["Wissen Sie schon von unserem neuesten Projekt?"], "_exampleTrans": {"en": "Do you already know about our newest project?", "tr": "En yeni projemizden haberiniz var mı?", "ru": "Вы уже знаете о нашем новейшем проекте?", "uk": "Ви вже знаєте про наш найновіший проєкт?", "es": "¿Ya sabe usted de nuestro proyecto más reciente?", "fa": "آیا از جدیدترین پروژهٔ ما خبر دارید؟", "ar": "هل تعرفون بالفعل عن أحدث مشاريعنا؟"}}, {"id": "vap_8374f5ed026b", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich zurückziehen + von/aus", "cat": "vp", "syn": ["sich zurückziehen", "austreten", "sich entfernen", "zurücktreten"], "ex": ["Sie hat sich von dem Projekt zurückgezogen."], "_exampleTrans": {"en": "She withdrew from the project.", "tr": "Projeden çekildi.", "ru": "Она вышла из проекта.", "uk": "Вона вийшла з проєкту.", "es": "Ella se retiró del proyecto.", "fa": "او از پروژه کنار کشید.", "ar": "انسحبت من المشروع."}}, {"id": "vap_fe5dd9ff4120", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich ekeln + vor", "cat": "vp", "syn": ["sich ekeln", "sich grauen", "sich abstoßen lassen", "Ekel empfinden"], "ex": ["Karla ekelt sich vor Spinnen."], "_exampleTrans": {"en": "Karla is disgusted by spiders.", "tr": "Karla örümceklerden iğreniyor.", "ru": "Карлу тошнит от пауков.", "uk": "Карлі огидні павуки.", "es": "A Karla le dan asco las arañas.", "fa": "کارلا از عنکبوت‌ها چندش می‌شود.", "ar": "تشمئز كارلا من العناكب."}}, {"id": "vap_0457c6f82133", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "flüchten + vor", "cat": "vp", "syn": ["fliehen", "entkommen", "weglaufen", "sich retten"], "ex": ["Sie flüchteten vor Unterdrückung."], "_exampleTrans": {"en": "They fled from oppression.", "tr": "Baskıdan kaçtılar.", "ru": "Они бежали от угнетения.", "uk": "Вони втекли від утисків.", "es": "Huyeron de la opresión.", "fa": "آن‌ها از سرکوب گریختند.", "ar": "هربوا من القمع."}}, {"id": "vap_ef624210756a", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich fürchten + vor", "cat": "vp", "syn": ["Angst haben", "sich sorgen", "sich ängstigen", "befürchten"], "ex": ["Viele Menschen fürchten sich vor der Klimaerwärmung."], "_exampleTrans": {"en": "Many people are afraid of global warming.", "tr": "Birçok insan küresel ısınmadan korkuyor.", "ru": "Многие люди боятся глобального потепления.", "uk": "Багато людей бояться глобального потепління.", "es": "Muchas personas temen el calentamiento global.", "fa": "بسیاری از مردم از گرمایش جهانی می‌ترسند.", "ar": "يخاف كثير من الناس من الاحترار المناخي."}}, {"id": "vap_77ae46c2f1a8", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich rechtfertigen + vor", "cat": "vp", "syn": ["begründen", "verteidigen", "erklären", "legitimieren"], "ex": ["Er musste sich vor seinem Chef rechtfertigen."], "_exampleTrans": {"en": "He had to justify himself before his boss.", "tr": "Patronunun karşısında kendini haklı göstermek zorunda kaldı.", "ru": "Ему пришлось оправдываться перед своим начальником.", "uk": "Йому довелося виправдовуватися перед своїм начальником.", "es": "Tuvo que justificarse ante su jefe.", "fa": "او مجبور شد نزد رئیسش از خود دفاع کند.", "ar": "اضطر إلى تبرير موقفه أمام مديره."}}, {"id": "vap_1ee846ebdb6d", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "schützen + vor", "cat": "vp", "syn": ["bewahren", "absichern", "verteidigen", "schützen"], "ex": ["Diese Jacke schützt vor Regen."], "_exampleTrans": {"en": "This jacket protects against rain.", "tr": "Bu ceket yağmurdan korur.", "ru": "Эта куртка защищает от дождя.", "uk": "Ця куртка захищає від дощу.", "es": "Esta chaqueta protege de la lluvia.", "fa": "این کاپشن در برابر باران محافظت می‌کند.", "ar": "تحمي هذه السترة من المطر."}}, {"id": "vap_68d772ec07c4", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "warnen + vor", "cat": "vp", "syn": ["mahnen", "warnen", "aufmerksam machen", "alarmieren"], "ex": ["Er warnte sie vor einer Zusammenarbeit mit dieser Firma."], "_exampleTrans": {"en": "He warned her against cooperating with this company.", "tr": "Onu bu firmayla iş birliği yapmaması konusunda uyardı.", "ru": "Он предостерёг её от сотрудничества с этой фирмой.", "uk": "Він застеріг її від співпраці з цією фірмою.", "es": "La advirtió contra una colaboración con esta empresa.", "fa": "او را از همکاری با این شرکت هشدار داد.", "ar": "حذّرها من التعاون مع هذه الشركة."}}, {"id": "vap_64109558b4c3", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich aufraffen + zu", "cat": "vp", "syn": ["sich überwinden", "sich aufmachen", "Mut fassen", "sich motivieren"], "ex": ["Er raffte sich dazu auf, etwas für das Projekt zu tun."], "_exampleTrans": {"en": "He pulled himself together to do something for the project.", "tr": "Proje için bir şeyler yapmak üzere kendini toparladı.", "ru": "Он собрался с силами, чтобы сделать что-то для проекта.", "uk": "Він зібрався з силами, щоб зробити щось для проєкту.", "es": "Se animó a hacer algo por el proyecto.", "fa": "او خود را جمع‌وجور کرد تا کاری برای پروژه انجام دهد.", "ar": "استجمع قواه ليفعل شيئًا من أجل المشروع."}}, {"id": "vap_8a6d2e22ba38", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "beitragen + zu", "cat": "vp", "syn": ["mitwirken", "beisteuern", "unterstützen", "fördern"], "ex": ["Sie hat viel zum Erfolg des Teams beigetragen."], "_exampleTrans": {"en": "She contributed a lot to the success of the team.", "tr": "Takımın başarısına çok katkıda bulundu.", "ru": "Она много способствовала успеху команды.", "uk": "Вона багато сприяла успіху команди.", "es": "Contribuyó mucho al éxito del equipo.", "fa": "او سهم زیادی در موفقیت تیم داشت.", "ar": "أسهمت كثيرًا في نجاح الفريق."}}, {"id": "vap_2a7f2b5ad2bc", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "drängen + zu", "cat": "vp", "syn": ["antreiben", "nötigen", "drängen", "hinwirken"], "ex": ["Sie drängte ihn zum Einverständnis."], "_exampleTrans": {"en": "She urged him to agree.", "tr": "Onu onay vermeye zorladı.", "ru": "Она подтолкнула его к согласию.", "uk": "Вона схилила його до згоди.", "es": "Ella lo presionó para que diera su consentimiento.", "fa": "او او را به موافقت واداشت.", "ar": "ضغطت عليه للموافقة."}}, {"id": "vap_6ff751e204b2", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "einladen + zu", "cat": "vp", "syn": ["auffordern", "bitten", "einbestellen", "zu Gast bitten"], "ex": ["Die Geschäftsführung hat Journalisten zum Pressefest eingeladen."], "_exampleTrans": {"en": "The management invited journalists to the press event.", "tr": "Yönetim gazetecileri basın etkinliğine davet etti.", "ru": "Руководство пригласило журналистов на пресс-мероприятие.", "uk": "Керівництво запросило журналістів на пресовий захід.", "es": "La dirección invitó a periodistas al evento de prensa.", "fa": "مدیریت روزنامه‌نگاران را به مراسم مطبوعاتی دعوت کرد.", "ar": "دعت الإدارة الصحفيين إلى فعالية صحفية."}}, {"id": "vap_06d7a04d93a5", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "sich entwickeln + zu", "cat": "vp", "syn": ["sich herausbilden", "werden", "wachsen", "sich entfalten"], "ex": ["Er hat sich zu einem guten Mitarbeiter entwickelt."], "_exampleTrans": {"en": "He developed into a good employee.", "tr": "İyi bir çalışana dönüştü.", "ru": "Он превратился в хорошего сотрудника.", "uk": "Він перетворився на хорошого працівника.", "es": "Se ha convertido en un buen empleado.", "fa": "او به یک کارمند خوب تبدیل شد.", "ar": "تطوّر ليصبح موظفًا جيدًا."}}, {"id": "vap_f461f97d7ebe", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "führen + zu", "cat": "vp", "syn": ["verursachen", "bewirken", "leiten", "resultieren"], "ex": ["Diese Diskussion führt zu keinem Ergebnis."], "_exampleTrans": {"en": "This discussion leads to no result.", "tr": "Bu tartışma hiçbir sonuca götürmüyor.", "ru": "Эта дискуссия ни к какому результату не приводит.", "uk": "Ця дискусія не приводить до жодного результату.", "es": "Esta discusión no conduce a ningún resultado.", "fa": "این بحث به هیچ نتیجه‌ای نمی‌رسد.", "ar": "لا تؤدي هذه المناقشة إلى أي نتيجة."}}, {"id": "vap_8c1a10426db1", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "gehören + zu", "cat": "vp", "syn": ["zugeordnet sein", "zählen zu", "dazugehören", "angehören"], "ex": ["Gehören Sie auch zu dieser Firma?"], "_exampleTrans": {"en": "Do you also belong to this company?", "tr": "Siz de bu firmaya mı aitsiniz?", "ru": "Вы тоже принадлежите к этой фирме?", "uk": "Ви також належите до цієї фірми?", "es": "¿También pertenece usted a esta empresa?", "fa": "آیا شما هم به این شرکت تعلق دارید؟", "ar": "هل تنتمون أنتم أيضًا إلى هذه الشركة؟"}}, {"id": "vap_d2e8758fe3c0", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "gratulieren + zu", "cat": "vp", "syn": ["beglückwünschen", "Glück wünschen", "gratulieren", "Glückwünsche aussprechen"], "ex": ["Ich gratuliere dir zum Geburtstag."], "_exampleTrans": {"en": "I congratulate you on your birthday.", "tr": "Doğum gününü kutlarım.", "ru": "Я поздравляю тебя с днём рождения.", "uk": "Я вітаю тебе з днем народження.", "es": "Te felicito por tu cumpleaños.", "fa": "تولدت را تبریک می‌گویم.", "ar": "أهنئك بعيد ميلادك."}}, {"id": "vap_bdad0a4259ab", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "kommen + zu/auf", "cat": "vp", "syn": ["gelangen", "entstehen", "eintreten", "kommen"], "ex": ["Wegen des Nebels kam es zu vielen Unfällen."], "_exampleTrans": {"en": "Because of the fog, many accidents occurred.", "tr": "Sis nedeniyle birçok kaza meydana geldi.", "ru": "Из-за тумана произошло много аварий.", "uk": "Через туман сталося багато аварій.", "es": "A causa de la niebla se produjeron muchos accidentes.", "fa": "به دلیل مه، حوادث زیادی رخ داد.", "ar": "بسبب الضباب وقعت حوادث كثيرة."}}, {"id": "vap_338f27cef4ba", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "meinen + zu", "cat": "vp", "syn": ["denken", "finden", "der Ansicht sein", "meinen"], "ex": ["Was meinen Sie zu meinem Vorschlag?"], "_exampleTrans": {"en": "What do you think of my proposal?", "tr": "Önerim hakkında ne düşünüyorsunuz?", "ru": "Что Вы думаете о моём предложении?", "uk": "Що Ви думаєте про мою пропозицію?", "es": "¿Qué opina usted de mi propuesta?", "fa": "نظر شما دربارهٔ پیشنهاد من چیست؟", "ar": "ما رأيكم في اقتراحي؟"}}, {"id": "vap_8487ee251deb", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "passen + zu", "cat": "vp", "syn": ["geeignet sein", "entsprechen", "harmonieren", "passen"], "ex": ["Welche Fähigkeiten von Ihnen passen zu diesem Beruf?"], "_exampleTrans": {"en": "Which of your skills suit this profession?", "tr": "Hangi becerileriniz bu mesleğe uyuyor?", "ru": "Какие Ваши способности подходят к этой профессии?", "uk": "Які Ваші здібності підходять до цієї професії?", "es": "¿Qué habilidades suyas encajan con esta profesión?", "fa": "کدام توانایی‌های شما با این شغل مناسب است؟", "ar": "أي من مهاراتكم يناسب هذه المهنة؟"}}, {"id": "vap_c9c0047259b9", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "vp", "word": "wählen + zu", "cat": "vp", "syn": ["auswählen", "bestimmen", "wählen", "ernennen"], "ex": ["Michaela König wurde gestern zur Betriebsrätin gewählt."], "_exampleTrans": {"en": "Michaela König was elected works councilor yesterday.", "tr": "Michaela König dün işyeri temsilcisi seçildi.", "ru": "Михаэла Кёниг вчера была избрана членом производственного совета.", "uk": "Міхаела Кеніг учора була обрана членкинею виробничої ради.", "es": "Michaela König fue elegida ayer miembro del comité de empresa.", "fa": "میشائلا کونیگ دیروز به‌عنوان عضو شورای کارگاه انتخاب شد.", "ar": "انتُخبت ميخائيلا كونيغ أمس عضوةً في مجلس العاملين."}}, {"id": "vap_d66bfd912f3d", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "beteiligt + an", "cat": "ap", "syn": ["involviert", "beteiligt", "mitwirkend", "eingebunden"], "ex": ["Sie waren an der Umsetzung des Investitionsplans beteiligt."], "_exampleTrans": {"en": "They were involved in the implementation of the investment plan.", "tr": "Yatırım planının uygulanmasına dâhil oldular.", "ru": "Они участвовали в реализации инвестиционного плана.", "uk": "Вони були залучені до реалізації інвестиційного плану.", "es": "Participaron en la implementación del plan de inversión.", "fa": "آن‌ها در اجرای طرح سرمایه‌گذاری مشارکت داشتند.", "ar": "كانوا مشاركين في تنفيذ خطة الاستثمار."}}, {"id": "vap_cdf4c447da2d", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "gewöhnt + an", "cat": "ap", "syn": ["vertraut", "eingewöhnt", "gewohnt", "angepasst"], "ex": ["Die Sekretärin ist an das alte Betriebssystem gewöhnt."], "_exampleTrans": {"en": "The secretary is used to the old operating system.", "tr": "Sekreter eski işletim sistemine alışkın.", "ru": "Секретарь привыкла к старой операционной системе.", "uk": "Секретарка звикла до старої операційної системи.", "es": "La secretaria está acostumbrada al antiguo sistema operativo.", "fa": "منشی به سیستم‌عامل قدیمی عادت دارد.", "ar": "اعتادت السكرتيرة على نظام التشغيل القديم."}}, {"id": "vap_9222b5e72ca7", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "interessiert + an", "cat": "ap", "syn": ["neugierig", "aufgeschlossen", "interessiert", "beteiligt"], "ex": ["Sie war an der ausgeschriebenen Stelle interessiert."], "_exampleTrans": {"en": "She was interested in the advertised position.", "tr": "İlan edilen pozisyonla ilgileniyordu.", "ru": "Она была заинтересована в объявленной вакансии.", "uk": "Вона була зацікавлена у оголошеній посаді.", "es": "Ella estaba interesada en el puesto anunciado.", "fa": "او به موقعیت شغلی اعلام‌شده علاقه‌مند بود.", "ar": "كانت مهتمة بالوظيفة المعلنة."}}, {"id": "vap_20b95bd7aa3e", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "reich + an", "cat": "ap", "syn": ["voll", "wohlhabend", "reichhaltig", "ergiebig"], "ex": ["Das Geschäftsjahr war reich an unangenehmen Überraschungen."], "_exampleTrans": {"en": "The financial year was rich in unpleasant surprises.", "tr": "Mali yıl hoş olmayan sürprizlerle doluydu.", "ru": "Финансовый год был богат неприятными сюрпризами.", "uk": "Фінансовий рік був багатий на неприємні сюрпризи.", "es": "El ejercicio fue rico en sorpresas desagradables.", "fa": "سال مالی پر از شگفتی‌های ناخوشایند بود.", "ar": "كان العام المالي مليئًا بالمفاجآت غير السارة."}}, {"id": "vap_61f6618380ba", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "schuld + an", "cat": "ap", "syn": ["verantwortlich", "schuldig", "ursächlich", "haftbar"], "ex": ["Wer war an dem Betriebsunfall schuld?"], "_exampleTrans": {"en": "Who was to blame for the workplace accident?", "tr": "İş kazasından kim sorumluydu?", "ru": "Кто был виноват в производственной аварии?", "uk": "Хто був винен у виробничому нещасному випадку?", "es": "¿Quién tuvo la culpa del accidente laboral?", "fa": "چه کسی در حادثهٔ کاری مقصر بود؟", "ar": "من كان مسؤولًا عن حادث العمل؟"}}, {"id": "vap_9696ad28efef", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "unschuldig + an", "cat": "ap", "syn": ["unbeteiligt", "schuldlos", "unschuldig", "nicht verantwortlich"], "ex": ["Sie war an der Sache nicht ganz unschuldig."], "_exampleTrans": {"en": "She was not entirely innocent in the matter.", "tr": "Bu konuda tamamen masum değildi.", "ru": "В этом деле она была не совсем невиновна.", "uk": "У цій справі вона була не зовсім невинна.", "es": "Ella no era del todo inocente en el asunto.", "fa": "او در این قضیه کاملاً بی‌گناه نبود.", "ar": "لم تكن بريئة تمامًا في هذه المسألة."}}, {"id": "vap_cf348ff3d44c", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "angewiesen + auf", "cat": "ap", "syn": ["abhängig", "gebunden", "angewiesen", "auf Hilfe angewiesen"], "ex": ["Wir sind auf das Funktionieren der Software angewiesen."], "_exampleTrans": {"en": "We depend on the software functioning.", "tr": "Yazılımın çalışmasına bağımlıyız.", "ru": "Мы зависим от функционирования программного обеспечения.", "uk": "Ми залежимо від функціонування програмного забезпечення.", "es": "Dependemos del funcionamiento del software.", "fa": "ما به کارکرد نرم‌افزار وابسته‌ایم.", "ar": "نحن معتمدون على عمل البرنامج."}}, {"id": "vap_d341a936eebe", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "böse + auf", "cat": "ap", "syn": ["verärgert", "wütend", "sauer", "zornig"], "ex": ["Wegen des vergessenen Termins war sie auf ihren Kollegen böse."], "_exampleTrans": {"en": "Because of the forgotten appointment, she was angry with her colleague.", "tr": "Unutulan randevu yüzünden meslektaşına kızgındı.", "ru": "Из-за забытой встречи она злилась на своего коллегу.", "uk": "Через забутий термін вона злилася на свого колегу.", "es": "A causa de la cita olvidada, estaba enfadada con su colega.", "fa": "به خاطر قرار فراموش‌شده از همکارش عصبانی بود.", "ar": "بسبب الموعد المنسي كانت غاضبة من زميلها."}}, {"id": "vap_35286804b547", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "eifersüchtig + auf", "cat": "ap", "syn": ["neidisch", "eifersüchtig", "missgünstig", "besitzergreifend"], "ex": ["Das Kind war auf das Spielzeug eines anderen eifersüchtig."], "_exampleTrans": {"en": "The child was jealous of another child's toy.", "tr": "Çocuk başka birinin oyuncağını kıskanıyordu.", "ru": "Ребёнок завидовал игрушке другого ребёнка.", "uk": "Дитина заздрила іграшці іншої дитини.", "es": "El niño estaba celoso del juguete de otro.", "fa": "کودک به اسباب‌بازی فرد دیگری حسادت می‌کرد.", "ar": "كان الطفل يغار من لعبة طفل آخر."}}, {"id": "vap_0db509e47cf6", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "gespannt + auf", "cat": "ap", "syn": ["neugierig", "erwartungsvoll", "aufmerksam", "angespannt"], "ex": ["Die Mitarbeitenden waren auf die Rede des Betriebsrats gespannt."], "_exampleTrans": {"en": "The employees were eager to hear the speech of the works council.", "tr": "Çalışanlar işletme kurulunun konuşmasını merakla bekliyordu.", "ru": "Сотрудники с нетерпением ждали речи производственного совета.", "uk": "Працівники з нетерпінням чекали на промову виробничої ради.", "es": "Los empleados estaban expectantes ante el discurso del comité de empresa.", "fa": "کارکنان مشتاق سخنرانی شورای کارگاه بودند.", "ar": "كان الموظفون متشوقين لخطاب مجلس العاملين."}}, {"id": "vap_bb8fb79e5de8", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "neidisch + auf", "cat": "ap", "syn": ["eifersüchtig", "missgünstig", "neidvoll", "neidisch"], "ex": ["Er war auf seinen Kollegen, der befördert wurde, neidisch."], "_exampleTrans": {"en": "He was jealous of his colleague, who was promoted.", "tr": "Terfi ettirilen meslektaşını kıskanıyordu.", "ru": "Он завидовал своему коллеге, которого повысили.", "uk": "Він заздрив своєму колезі, якого підвищили.", "es": "Estaba celoso de su colega, que fue ascendido.", "fa": "او به همکارش که ترفیع گرفته بود حسادت می‌کرد.", "ar": "كان يغار من زميله الذي تمت ترقيته."}}, {"id": "vap_97955bb91eed", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "neugierig + auf", "cat": "ap", "syn": ["interessiert", "wissbegierig", "gespannt", "neugierig"], "ex": ["Sie waren auf das Ergebnis der Gespräche neugierig."], "_exampleTrans": {"en": "They were curious about the result of the talks.", "tr": "Görüşmelerin sonucunu merak ediyorlardı.", "ru": "Им было интересно узнать результат переговоров.", "uk": "Їм було цікаво дізнатися результат переговорів.", "es": "Tenían curiosidad por el resultado de las conversaciones.", "fa": "آن‌ها دربارهٔ نتیجهٔ گفت‌وگوها کنجکاو بودند.", "ar": "كانوا فضوليين بشأن نتيجة المحادثات."}}, {"id": "vap_f2536b28c139", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "stolz + auf", "cat": "ap", "syn": ["erfüllt", "selbstbewusst", "stolz", "erhoben"], "ex": ["Sie war auf die guten Leistungen ihres Teams stolz."], "_exampleTrans": {"en": "She was proud of her team's good performance.", "tr": "Ekibinin iyi performansıyla gurur duyuyordu.", "ru": "Она гордилась хорошими результатами своей команды.", "uk": "Вона пишалася добрими результатами своєї команди.", "es": "Estaba orgullosa de los buenos resultados de su equipo.", "fa": "او به عملکرد خوب تیمش افتخار می‌کرد.", "ar": "كانت فخورة بالأداء الجيد لفريقها."}}, {"id": "vap_bf1cf8c8a63a", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "wütend + auf/über", "cat": "ap", "syn": ["zornig", "verärgert", "rasend", "wütend"], "ex": ["Nach dem Meeting war die Chefin auf das Team ziemlich wütend."], "_exampleTrans": {"en": "After the meeting, the boss was quite angry with the team.", "tr": "Toplantıdan sonra patron ekibe oldukça kızgındı.", "ru": "После совещания начальница была довольно зла на команду.", "uk": "Після наради начальниця була досить зла на команду.", "es": "Después de la reunión, la jefa estaba bastante enfadada con el equipo.", "fa": "بعد از جلسه، رئیس از تیم نسبتاً عصبانی بود.", "ar": "بعد الاجتماع كانت المديرة غاضبة جدًا من الفريق."}}, {"id": "vap_842c8027011d", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "angesehen + bei", "cat": "ap", "syn": ["geachtet", "respektiert", "renommiert", "anerkannt"], "ex": ["Sie war bei ihren Geschäftspartnern hoch angesehen."], "_exampleTrans": {"en": "She was highly respected by her business partners.", "tr": "İş ortakları arasında çok saygı görüyordu.", "ru": "Она пользовалась большим уважением у своих деловых партнёров.", "uk": "Вона користувалася великою повагою серед своїх ділових партнерів.", "es": "Ella gozaba de gran prestigio entre sus socios comerciales.", "fa": "او نزد شرکای تجاری‌اش بسیار محترم بود.", "ar": "كانت تحظى باحترام كبير لدى شركائها التجاريين."}}, {"id": "vap_acc8f439ed79", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "behilflich + bei", "cat": "ap", "syn": ["hilfreich", "unterstützend", "dienlich", "nützlich"], "ex": ["Kannst du mir bei der Installation des Programms behilflich sein?"], "_exampleTrans": {"en": "Can you help me with the installation of the program?", "tr": "Programın kurulumunda bana yardımcı olabilir misin?", "ru": "Можешь помочь мне с установкой программы?", "uk": "Можеш допомогти мені з установленням програми?", "es": "¿Puedes ayudarme con la instalación del programa?", "fa": "می‌توانی در نصب برنامه به من کمک کنی؟", "ar": "هل يمكنك مساعدتي في تثبيت البرنامج؟"}}, {"id": "vap_186c9794357b", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "beliebt + bei", "cat": "ap", "syn": ["geschätzt", "populär", "gern gesehen", "angesehen"], "ex": ["Die Internationale Funkausstellung ist bei den Besuchern sehr beliebt."], "_exampleTrans": {"en": "The International Radio Exhibition is very popular with visitors.", "tr": "Uluslararası Radyo Fuarı ziyaretçiler arasında çok popülerdir.", "ru": "Международная выставка радиоэлектроники очень популярна среди посетителей.", "uk": "Міжнародна радіовиставка дуже популярна серед відвідувачів.", "es": "La Exposición Internacional de Radio es muy popular entre los visitantes.", "fa": "نمایشگاه بین‌المللی رادیو در میان بازدیدکنندگان بسیار محبوب است.", "ar": "المعرض الدولي للإذاعة محبوب جدًا لدى الزوار."}}, {"id": "vap_2b630e38bf53", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "unbeliebt + bei", "cat": "ap", "syn": ["unpopulär", "nicht geschätzt", "unbeliebt", "missliebig"], "ex": ["Der Chef war bei einigen Mitarbeitenden ziemlich unbeliebt."], "_exampleTrans": {"en": "The boss was quite unpopular with some employees.", "tr": "Patron bazı çalışanlar arasında oldukça sevilmiyordu.", "ru": "Начальник был довольно непопулярен среди некоторых сотрудников.", "uk": "Начальник був досить непопулярним серед деяких працівників.", "es": "El jefe era bastante impopular entre algunos empleados.", "fa": "رئیس نزد بعضی از کارکنان نسبتاً نامحبوب بود.", "ar": "كان المدير غير محبوب إلى حدّ كبير لدى بعض الموظفين."}}, {"id": "vap_75a71630a81b", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "angenehm + für", "cat": "ap", "syn": ["erfreulich", "wohltuend", "angenehm", "komfortabel"], "ex": ["Das Arbeitsklima im Projekt war für die Mitarbeitenden sehr angenehm."], "_exampleTrans": {"en": "The working atmosphere in the project was very pleasant for the employees.", "tr": "Projede çalışma ortamı çalışanlar için çok hoştu.", "ru": "Рабочая атмосфера в проекте была очень приятной для сотрудников.", "uk": "Робоча атмосфера в проєкті була дуже приємною для працівників.", "es": "El ambiente de trabajo en el proyecto fue muy agradable para los empleados.", "fa": "فضای کاری در پروژه برای کارکنان بسیار خوشایند بود.", "ar": "كان جو العمل في المشروع مريحًا جدًا للموظفين."}}, {"id": "vap_cd675421c6e2", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "bekannt + für/mit", "cat": "ap", "syn": ["vertraut", "berühmt", "geläufig", "namhaft"], "ex": ["Sie ist in der Abteilung für ihre Genauigkeit bekannt."], "_exampleTrans": {"en": "She is known in the department for her precision.", "tr": "Bölümde titizliğiyle tanınır.", "ru": "В отделе она известна своей точностью.", "uk": "У відділі вона відома своєю точністю.", "es": "En el departamento es conocida por su precisión.", "fa": "او در بخش به خاطر دقتش شناخته شده است.", "ar": "هي معروفة في القسم بدقتها."}}, {"id": "vap_9f2160985b9f", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "berühmt + für", "cat": "ap", "syn": ["bekannt", "renommiert", "prominent", "gefeiert"], "ex": ["Die Firma ist für ihre Hebebühnen weltweit berühmt."], "_exampleTrans": {"en": "The company is famous worldwide for its lifting platforms.", "tr": "Şirket kaldırma platformlarıyla dünya çapında ünlüdür.", "ru": "Фирма известна во всём мире своими подъёмными платформами.", "uk": "Фірма відома в усьому світі своїми підйомними платформами.", "es": "La empresa es famosa en todo el mundo por sus plataformas elevadoras.", "fa": "شرکت به خاطر بالابرهایش در سراسر جهان معروف است.", "ar": "الشركة مشهورة عالميًا بمنصات الرفع الخاصة بها."}}, {"id": "vap_61877c02e9dd", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "dankbar + für", "cat": "ap", "syn": ["erkenntlich", "dankerfüllt", "verpflichtet", "dankbar"], "ex": ["Die Chefin ist immer für Verbesserungsvorschläge dankbar."], "_exampleTrans": {"en": "The boss is always grateful for suggestions for improvement.", "tr": "Patron, iyileştirme önerileri için her zaman minnettardır.", "ru": "Начальница всегда благодарна за предложения по улучшению.", "uk": "Начальниця завжди вдячна за пропозиції щодо поліпшення.", "es": "La jefa siempre está agradecida por las propuestas de mejora.", "fa": "رئیس همیشه بابت پیشنهادهای بهبود سپاسگزار است.", "ar": "المديرة ممتنة دائمًا لمقترحات التحسين."}}, {"id": "vap_7ba39be58887", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "entscheidend + für", "cat": "ap", "syn": ["ausschlaggebend", "maßgeblich", "wesentlich", "entscheidend"], "ex": ["Die gute Zusammenarbeit im Projekt war für den Erfolg entscheidend."], "_exampleTrans": {"en": "The good cooperation in the project was decisive for the success.", "tr": "Projede iyi iş birliği başarı için belirleyiciydi.", "ru": "Хорошее сотрудничество в проекте было решающим для успеха.", "uk": "Добра співпраця в проєкті була вирішальною для успіху.", "es": "La buena colaboración en el proyecto fue decisiva para el éxito.", "fa": "همکاری خوب در پروژه برای موفقیت تعیین‌کننده بود.", "ar": "كان التعاون الجيد في المشروع حاسمًا للنجاح."}}, {"id": "vap_9fdef773569a", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "geeignet + für", "cat": "ap", "syn": ["passend", "tauglich", "zweckmäßig", "geeignet"], "ex": ["Die Buchhaltungssoftware ist insbesondere für kleine Unternehmen geeignet."], "_exampleTrans": {"en": "The accounting software is suitable especially for small businesses.", "tr": "Muhasebe yazılımı özellikle küçük işletmeler için uygundur.", "ru": "Бухгалтерское программное обеспечение особенно подходит для малых предприятий.", "uk": "Бухгалтерське програмне забезпечення особливо підходить для малих підприємств.", "es": "El software de contabilidad es especialmente adecuado para pequeñas empresas.", "fa": "نرم‌افزار حسابداری به‌ویژه برای شرکت‌های کوچک مناسب است.", "ar": "برنامج المحاسبة مناسب خصوصًا للشركات الصغيرة."}}, {"id": "vap_1d79bcd56cc0", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "offen + für", "cat": "ap", "syn": ["aufgeschlossen", "empfänglich", "bereit", "offen"], "ex": ["Wir sind für alle Verbesserungsvorschläge offen."], "_exampleTrans": {"en": "We are open to all suggestions for improvement.", "tr": "Tüm iyileştirme önerilerine açığız.", "ru": "Мы открыты для всех предложений по улучшению.", "uk": "Ми відкриті до всіх пропозицій щодо поліпшення.", "es": "Estamos abiertos a todas las propuestas de mejora.", "fa": "ما پذیرای همهٔ پیشنهادهای بهبود هستیم.", "ar": "نحن منفتحون على جميع مقترحات التحسين."}}, {"id": "vap_3cca466e6d12", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "schädlich + für", "cat": "ap", "syn": ["schädigend", "nachteilig", "gefährlich", "schädlich"], "ex": ["Das Produktionsverfahren ist für die Umwelt nicht schädlich."], "_exampleTrans": {"en": "The production process is not harmful to the environment.", "tr": "Üretim yöntemi çevre için zararlı değildir.", "ru": "Производственный процесс не вреден для окружающей среды.", "uk": "Виробничий процес не шкідливий для довкілля.", "es": "El proceso de producción no es perjudicial para el medio ambiente.", "fa": "فرایند تولید برای محیط زیست زیان‌آور نیست.", "ar": "عملية الإنتاج ليست ضارة بالبيئة."}}, {"id": "vap_60bda95b1ef7", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "schwierig + für", "cat": "ap", "syn": ["kompliziert", "schwer", "anspruchsvoll", "schwierig"], "ex": ["Eine Umstrukturierung ist für die Mitarbeitenden immer schwierig."], "_exampleTrans": {"en": "A restructuring is always difficult for the employees.", "tr": "Yeniden yapılanma çalışanlar için her zaman zordur.", "ru": "Реструктуризация всегда трудна для сотрудников.", "uk": "Реструктуризація завжди складна для працівників.", "es": "Una reestructuración siempre es difícil para los empleados.", "fa": "بازسازی سازمانی همیشه برای کارکنان دشوار است.", "ar": "إعادة الهيكلة صعبة دائمًا على الموظفين."}}, {"id": "vap_6f3f20047242", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "typisch + für", "cat": "ap", "syn": ["charakteristisch", "bezeichnend", "typisch", "kennzeichnend"], "ex": ["Das ist mal wieder typisch für Sie."], "_exampleTrans": {"en": "That is typical of you again.", "tr": "Bu yine tam size göre.", "ru": "Это опять типично для Вас.", "uk": "Це знову типово для Вас.", "es": "Eso es otra vez típico de usted.", "fa": "این باز هم از شما بعید نیست.", "ar": "هذا نمطي منكم مرة أخرى."}}, {"id": "vap_bb81bb129fb7", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "unangenehm + für", "cat": "ap", "syn": ["lästig", "peinlich", "unerfreulich", "unangenehm"], "ex": ["Der Außendienstbericht war für den Verkaufsleiter sehr unangenehm."], "_exampleTrans": {"en": "The field service report was very unpleasant for the sales manager.", "tr": "Saha hizmeti raporu satış müdürü için çok rahatsız ediciydi.", "ru": "Отчёт внешней службы был очень неприятен для руководителя отдела продаж.", "uk": "Звіт зовнішньої служби був дуже неприємним для керівника відділу продажів.", "es": "El informe del servicio externo fue muy desagradable para el director de ventas.", "fa": "گزارش خدمات میدانی برای مدیر فروش بسیار ناخوشایند بود.", "ar": "كان تقرير الخدمة الميدانية مزعجًا جدًا لمدير المبيعات."}}, {"id": "vap_0c05a5062fd5", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "ungeeignet + für", "cat": "ap", "syn": ["unpassend", "untauglich", "ungeeignet", "unzweckmäßig"], "ex": ["Er ist für diese Arbeit gänzlich ungeeignet."], "_exampleTrans": {"en": "He is completely unsuitable for this work.", "tr": "Bu iş için tamamen uygun değil.", "ru": "Он совершенно не подходит для этой работы.", "uk": "Він зовсім не підходить для цієї роботи.", "es": "Él es totalmente inadecuado para este trabajo.", "fa": "او کاملاً برای این کار نامناسب است.", "ar": "إنه غير مناسب تمامًا لهذا العمل."}}, {"id": "vap_97df3d0b30ee", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "verantwortlich + für", "cat": "ap", "syn": ["zuständig", "verantwortlich", "haftbar", "maßgeblich"], "ex": ["Frau Dr. Blum war für die Entwicklung des neuen Produkts verantwortlich."], "_exampleTrans": {"en": "Dr. Blum was responsible for developing the new product.", "tr": "Dr. Blum yeni ürünün geliştirilmesinden sorumluydu.", "ru": "Фрау д-р Блюм отвечала за разработку нового продукта.", "uk": "Пані д-р Блюм відповідала за розробку нового продукту.", "es": "La Dra. Blum fue responsable del desarrollo del nuevo producto.", "fa": "خانم دکتر بلوم مسئول توسعهٔ محصول جدید بود.", "ar": "كانت الدكتورة بلوم مسؤولة عن تطوير المنتج الجديد."}}, {"id": "vap_b1144da52f04", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "wichtig + für", "cat": "ap", "syn": ["bedeutend", "wesentlich", "relevant", "wichtig"], "ex": ["Unser Engagement ist für den Erfolg des Projekts ziemlich wichtig."], "_exampleTrans": {"en": "Our commitment is quite important for the success of the project.", "tr": "Bağlılığımız projenin başarısı için oldukça önemlidir.", "ru": "Наша самоотдача довольно важна для успеха проекта.", "uk": "Наша відданість досить важлива для успіху проєкту.", "es": "Nuestro compromiso es bastante importante para el éxito del proyecto.", "fa": "تعهد ما برای موفقیت پروژه بسیار مهم است.", "ar": "التزامنا مهم جدًا لنجاح المشروع."}}, {"id": "vap_f719bb22fac7", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "zuständig + für", "cat": "ap", "syn": ["verantwortlich", "kompetent", "zuständig", "beauftragt"], "ex": ["Frau Duda ist für den Vertrieb zuständig."], "_exampleTrans": {"en": "Ms. Duda is responsible for sales.", "tr": "Bayan Duda satıştan sorumludur.", "ru": "Фрау Дуда отвечает за сбыт.", "uk": "Пані Дуда відповідає за збут.", "es": "La señora Duda es responsable de ventas.", "fa": "خانم دودا مسئول فروش است.", "ar": "السيدة دودا مسؤولة عن المبيعات."}}, {"id": "vap_f9f8ed5e5d0a", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "misstrauisch + gegenüber", "cat": "ap", "syn": ["skeptisch", "argwöhnisch", "misstrauisch", "zweifelnd"], "ex": ["Sie war gegenüber den Kollegen oft misstrauisch."], "_exampleTrans": {"en": "She was often distrustful toward her colleagues.", "tr": "Meslektaşlarına karşı sık sık güvensizdi.", "ru": "Она часто была недоверчива по отношению к коллегам.", "uk": "Вона часто була недовірливою до колег.", "es": "A menudo desconfiaba de sus colegas.", "fa": "او اغلب نسبت به همکارانش بدگمان بود.", "ar": "كانت غالبًا متشككة تجاه زملائها."}}, {"id": "vap_d82b1214f3f5", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "gut + in/zu", "cat": "ap", "syn": ["fähig", "stark", "geeignet", "freundlich"], "ex": ["Sie war in der Analyse von komplexen Daten schon immer sehr gut."], "_exampleTrans": {"en": "She had always been very good at analyzing complex data.", "tr": "Karmaşık verilerin analizinde her zaman çok iyiydi.", "ru": "Она всегда была очень сильна в анализе сложных данных.", "uk": "Вона завжди була дуже добра в аналізі складних даних.", "es": "Siempre fue muy buena en el análisis de datos complejos.", "fa": "او همیشه در تحلیل داده‌های پیچیده بسیار خوب بود.", "ar": "كانت دائمًا جيدة جدًا في تحليل البيانات المعقدة."}}, {"id": "vap_a0448c2e27b5", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "unerfahren + in", "cat": "ap", "syn": ["ungeübt", "unerprobt", "neu", "unerfahren"], "ex": ["Er war im Umgang mit der neuen Software unerfahren."], "_exampleTrans": {"en": "He was inexperienced in dealing with the new software.", "tr": "Yeni yazılımla çalışmada deneyimsizdi.", "ru": "Он был неопытен в обращении с новым программным обеспечением.", "uk": "Він був недосвідчений у роботі з новим програмним забезпеченням.", "es": "Era inexperto en el manejo del nuevo software.", "fa": "او در کار با نرم‌افزار جدید بی‌تجربه بود.", "ar": "كان قليل الخبرة في التعامل مع البرنامج الجديد."}}, {"id": "vap_2dbf045b48bf", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "verliebt + in", "cat": "ap", "syn": ["verknallt", "verliebt", "begeistert", "hingerissen"], "ex": ["Sie ist in ein kleines Hotel in den Allgäuer Alpen verliebt."], "_exampleTrans": {"en": "She is in love with a small hotel in the Allgäu Alps.", "tr": "Allgäu Alpleri’ndeki küçük bir otele âşık.", "ru": "Она влюблена в маленький отель в Альгойских Альпах.", "uk": "Вона закохана в маленький готель в Альгойських Альпах.", "es": "Está enamorada de un pequeño hotel en los Alpes de Allgäu.", "fa": "او عاشق یک هتل کوچک در آلپ‌های آلگاو است.", "ar": "هي مغرمة بفندق صغير في جبال الألب في ألغوي."}}, {"id": "vap_e062be1b3155", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "befreundet + mit", "cat": "ap", "syn": ["freundschaftlich verbunden", "gut bekannt", "vertraut", "nahestehend"], "ex": ["Er ist mit allen Kollegen gut befreundet."], "_exampleTrans": {"en": "He is good friends with all colleagues.", "tr": "Tüm meslektaşlarıyla iyi arkadaştır.", "ru": "Он хорошо дружит со всеми коллегами.", "uk": "Він добре товаришує з усіма колегами.", "es": "Es buen amigo de todos los colegas.", "fa": "او با همهٔ همکاران دوست خوبی است.", "ar": "هو صديق جيد لجميع الزملاء."}}, {"id": "vap_f44ca3481fc8", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "bekannt + mit/für", "cat": "ap", "syn": ["vertraut", "berühmt", "geläufig", "namhaft"], "ex": ["Sie ist mit allen Außendienstmitarbeitenden sehr gut bekannt."], "_exampleTrans": {"en": "She is very well acquainted with all field sales employees.", "tr": "Tüm saha satış çalışanlarıyla çok iyi tanışıktır.", "ru": "Она очень хорошо знакома со всеми сотрудниками выездной службы.", "uk": "Вона дуже добре знайома з усіма працівниками виїзної служби.", "es": "Ella conoce muy bien a todos los empleados del servicio externo.", "fa": "او با همهٔ کارکنان میدانی فروش بسیار خوب آشناست.", "ar": "هي على معرفة جيدة جدًا بجميع موظفي المبيعات الميدانيين."}}, {"id": "vap_b65b6397e09f", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "beschäftigt + mit", "cat": "ap", "syn": ["belegt", "ausgelastet", "in Arbeit", "eingebunden"], "ex": ["Frau Dr. Kurz ist noch mit dem Abschlussbericht beschäftigt."], "_exampleTrans": {"en": "Dr. Kurz is still busy with the final report.", "tr": "Dr. Kurz hâlâ nihai raporla meşgul.", "ru": "Фрау д-р Курц всё ещё занята итоговым отчётом.", "uk": "Пані д-р Курц ще зайнята підсумковим звітом.", "es": "La Dra. Kurz aún está ocupada con el informe final.", "fa": "خانم دکتر کورتس هنوز مشغول گزارش نهایی است.", "ar": "لا تزال الدكتورة كورتس مشغولة بالتقرير النهائي."}}, {"id": "vap_7a65215861e0", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "einverstanden + mit", "cat": "ap", "syn": ["zustimmend", "einig", "akzeptierend", "damit einverstanden"], "ex": ["Er ist mit seiner Versetzung in eine andere Abteilung einverstanden."], "_exampleTrans": {"en": "He agrees with his transfer to another department.", "tr": "Başka bir bölüme nakledilmesini kabul ediyor.", "ru": "Он согласен со своим переводом в другой отдел.", "uk": "Він згоден зі своїм переведенням в інший відділ.", "es": "Está de acuerdo con su traslado a otro departamento.", "fa": "او با انتقالش به بخش دیگری موافق است.", "ar": "إنه موافق على نقله إلى قسم آخر."}}, {"id": "vap_f7fc4e5650d7", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "fertig + mit", "cat": "ap", "syn": ["abgeschlossen", "beendet", "erledigt", "fertiggestellt"], "ex": ["Sind Sie mit dem Projektbericht schon fertig?"], "_exampleTrans": {"en": "Have you already finished the project report?", "tr": "Proje raporunu çoktan bitirdiniz mi?", "ru": "Вы уже закончили проектный отчёт?", "uk": "Ви вже закінчили проєктний звіт?", "es": "¿Ya ha terminado el informe del proyecto?", "fa": "آیا گزارش پروژه را تمام کرده‌اید؟", "ar": "هل انتهيتم بالفعل من تقرير المشروع؟"}}, {"id": "vap_4d9513b02fdd", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "unzufrieden + mit", "cat": "ap", "syn": ["missmutig", "enttäuscht", "unzufrieden", "unbefriedigt"], "ex": ["Die GF war mit der Geschäftsentwicklung unzufrieden."], "_exampleTrans": {"en": "The management was dissatisfied with the business development.", "tr": "Yönetim iş gelişiminden memnun değildi.", "ru": "Руководство было недовольно развитием бизнеса.", "uk": "Керівництво було незадоволене розвитком бізнесу.", "es": "La dirección estaba insatisfecha con el desarrollo del negocio.", "fa": "مدیریت از توسعهٔ کسب‌وکار ناراضی بود.", "ar": "كانت الإدارة غير راضية عن تطور الأعمال."}}, {"id": "vap_7689b3b7630c", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "verheiratet + mit", "cat": "ap", "syn": ["vermählt", "verheiratet", "in Ehe verbunden", "ehelich gebunden"], "ex": ["Er ist eigentlich mit seiner Arbeit verheiratet."], "_exampleTrans": {"en": "He is actually married to his work.", "tr": "O aslında işiyle evli.", "ru": "Он фактически женат на своей работе.", "uk": "Він фактично одружений зі своєю роботою.", "es": "En realidad está casado con su trabajo.", "fa": "او در واقع با کارش ازدواج کرده است.", "ar": "إنه في الحقيقة متزوج من عمله."}}, {"id": "vap_ae65e07f7aae", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "verwandt + mit", "cat": "ap", "syn": ["familiär verbunden", "verwandt", "ähnlich", "verbunden"], "ex": ["Er ist mit seinem Chef verwandt."], "_exampleTrans": {"en": "He is related to his boss.", "tr": "Patronuyla akrabadır.", "ru": "Он родственник своего начальника.", "uk": "Він родич свого начальника.", "es": "Está emparentado con su jefe.", "fa": "او با رئیسش خویشاوند است.", "ar": "هو قريب لمديره."}}, {"id": "vap_7a6186cddfbc", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "zufrieden + mit", "cat": "ap", "syn": ["einverstanden", "glücklich", "zufrieden", "erfüllt"], "ex": ["Unsere Kunden sind mit unseren Dienstleistungen sehr zufrieden."], "_exampleTrans": {"en": "Our customers are very satisfied with our services.", "tr": "Müşterilerimiz hizmetlerimizden çok memnun.", "ru": "Наши клиенты очень довольны нашими услугами.", "uk": "Наші клієнти дуже задоволені нашими послугами.", "es": "Nuestros clientes están muy satisfechos con nuestros servicios.", "fa": "مشتریان ما از خدماتمان بسیار راضی هستند.", "ar": "عملاؤنا راضون جدًا عن خدماتنا."}}, {"id": "vap_5946eb9d811d", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "verrückt + nach", "cat": "ap", "syn": ["versessen", "begeistert", "narrisch", "verrückt"], "ex": ["Sie ist wirklich völlig verrückt nach Fußball."], "_exampleTrans": {"en": "She is really completely crazy about football.", "tr": "Gerçekten futbola tamamen deli oluyor.", "ru": "Она действительно совершенно без ума от футбола.", "uk": "Вона справді зовсім божеволіє за футболом.", "es": "Está realmente loca por el fútbol.", "fa": "او واقعاً دیوانهٔ فوتبال است.", "ar": "إنها حقًا مجنونة تمامًا بكرة القدم."}}, {"id": "vap_35ca9f3873c8", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "besorgt + über/um", "cat": "ap", "syn": ["beunruhigt", "in Sorge", "bekümmert", "besorgt"], "ex": ["Die GF ist über die sinkenden Absatzzahlen sehr besorgt."], "_exampleTrans": {"en": "The management is very concerned about the falling sales figures.", "tr": "Yönetim düşen satış rakamlarından çok endişeli.", "ru": "Руководство очень обеспокоено падающими показателями продаж.", "uk": "Керівництво дуже занепокоєне падінням показників продажів.", "es": "La dirección está muy preocupada por la caída de las cifras de ventas.", "fa": "مدیریت به‌شدت نگران کاهش ارقام فروش است.", "ar": "الإدارة قلقة جدًا بشأن انخفاض أرقام المبيعات."}}, {"id": "vap_6acfceb48abb", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "beunruhigt + über", "cat": "ap", "syn": ["besorgt", "verunsichert", "alarmiert", "nervös"], "ex": ["Die Mitarbeitenden sind über die Umstrukturierungspläne beunruhigt."], "_exampleTrans": {"en": "The employees are worried about the restructuring plans.", "tr": "Çalışanlar yeniden yapılanma planlarından endişeli.", "ru": "Сотрудники обеспокоены планами реструктуризации.", "uk": "Працівники занепокоєні планами реструктуризації.", "es": "Los empleados están inquietos por los planes de reestructuración.", "fa": "کارکنان از برنامه‌های بازسازی سازمانی نگران‌اند.", "ar": "الموظفون قلقون بشأن خطط إعادة الهيكلة."}}, {"id": "vap_8780c1550859", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "entsetzt + über", "cat": "ap", "syn": ["schockiert", "bestürzt", "erschüttert", "fassungslos"], "ex": ["Sie war darüber, dass der Termin nicht eingehalten wird, entsetzt."], "_exampleTrans": {"en": "She was horrified that the appointment was not being kept.", "tr": "Randevuya uyulmayacağı için dehşete düştü.", "ru": "Она была в ужасе от того, что срок не будет соблюдён.", "uk": "Вона була нажахана тим, що термін не буде дотримано.", "es": "Estaba horrorizada de que no se cumpliera la cita.", "fa": "او از این‌که موعد رعایت نمی‌شود وحشت‌زده بود.", "ar": "كانت مصدومة من أن الموعد لن يُلتزم به."}}, {"id": "vap_e6dcda273f42", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "erstaunt + über", "cat": "ap", "syn": ["überrascht", "verwundert", "verblüfft", "erstaunt"], "ex": ["Die GF war über den Erfolg der Marketingkampagne erstaunt."], "_exampleTrans": {"en": "The management was amazed at the success of the marketing campaign.", "tr": "Yönetim pazarlama kampanyasının başarısına şaşırdı.", "ru": "Руководство было удивлено успехом маркетинговой кампании.", "uk": "Керівництво було здивоване успіхом маркетингової кампанії.", "es": "La dirección estaba asombrada por el éxito de la campaña de marketing.", "fa": "مدیریت از موفقیت کمپین بازاریابی شگفت‌زده شد.", "ar": "اندهشت الإدارة من نجاح حملة التسويق."}}, {"id": "vap_5e7f9688e3d0", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "froh + über", "cat": "ap", "syn": ["glücklich", "erleichtert", "erfreut", "zufrieden"], "ex": ["Die GF war über das positive Jahresergebnis sehr froh."], "_exampleTrans": {"en": "The management was very pleased about the positive annual result.", "tr": "Yönetim olumlu yıllık sonuçtan çok memnundu.", "ru": "Руководство было очень радо положительному годовому результату.", "uk": "Керівництво було дуже раде позитивному річному результату.", "es": "La dirección estaba muy contenta por el resultado anual positivo.", "fa": "مدیریت از نتیجهٔ مثبت سالانه بسیار خوشحال بود.", "ar": "كانت الإدارة سعيدة جدًا بالنتيجة السنوية الإيجابية."}}, {"id": "vap_7d0295090db9", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "glücklich + über", "cat": "ap", "syn": ["froh", "zufrieden", "selig", "erfreut"], "ex": ["Sie war über ihre Beförderung sehr glücklich."], "_exampleTrans": {"en": "She was very happy about her promotion.", "tr": "Terfisinden çok mutluydu.", "ru": "Она была очень счастлива из-за своего повышения.", "uk": "Вона була дуже щаслива через своє підвищення.", "es": "Estaba muy feliz por su ascenso.", "fa": "او از ترفیعش بسیار خوشحال بود.", "ar": "كانت سعيدة جدًا بترقيتها."}}, {"id": "vap_d6ea7ba9901a", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "unglücklich + über", "cat": "ap", "syn": ["betrübt", "traurig", "unzufrieden", "unglücklich"], "ex": ["Sie waren über seinen Weggang unglücklich."], "_exampleTrans": {"en": "They were unhappy about his departure.", "tr": "Onun ayrılışından mutsuzdular.", "ru": "Они были огорчены его уходом.", "uk": "Вони були засмучені його відходом.", "es": "Estaban descontentos por su partida.", "fa": "آن‌ها از رفتن او ناراحت بودند.", "ar": "كانوا غير سعداء برحيله."}}, {"id": "vap_bb8366639929", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "verärgert + über", "cat": "ap", "syn": ["wütend", "gereizt", "verärgert", "missgestimmt"], "ex": ["Er war über die Verzögerung im Projekt verärgert."], "_exampleTrans": {"en": "He was annoyed about the delay in the project.", "tr": "Projedeki gecikmeden rahatsızdı.", "ru": "Он был раздражён задержкой в проекте.", "uk": "Він був роздратований затримкою в проєкті.", "es": "Estaba molesto por el retraso en el proyecto.", "fa": "او از تأخیر در پروژه ناراحت بود.", "ar": "كان منزعجًا من التأخير في المشروع."}}, {"id": "vap_848fe3a9ed12", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "wütend + über/auf", "cat": "ap", "syn": ["zornig", "verärgert", "rasend", "wütend"], "ex": ["Viele Kunden waren über den schlechten Service wütend."], "_exampleTrans": {"en": "Many customers were angry about the poor service.", "tr": "Birçok müşteri kötü hizmetten öfkeliydi.", "ru": "Многие клиенты были злы из-за плохого сервиса.", "uk": "Багато клієнтів були розлючені через погане обслуговування.", "es": "Muchos clientes estaban enfadados por el mal servicio.", "fa": "بسیاری از مشتریان از خدمات بد عصبانی بودند.", "ar": "كان كثير من العملاء غاضبين من سوء الخدمة."}}, {"id": "vap_b6c8c1baf4e9", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "besorgt + um/über", "cat": "ap", "syn": ["beunruhigt", "in Sorge", "bekümmert", "besorgt"], "ex": ["Sie sind stets um das Wohl ihrer Gäste besorgt."], "_exampleTrans": {"en": "They are always concerned about the well-being of their guests.", "tr": "Misafirlerinin refahı için her zaman endişe duyarlar.", "ru": "Они всегда заботятся о благополучии своих гостей.", "uk": "Вони завжди дбають про добробут своїх гостей.", "es": "Siempre se preocupan por el bienestar de sus huéspedes.", "fa": "آن‌ها همیشه نگران رفاه مهمانانشان هستند.", "ar": "إنهم يهتمون دائمًا برفاه ضيوفهم."}}, {"id": "vap_83ec8da2fb89", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "abhängig + von", "cat": "ap", "syn": ["gebunden", "angewiesen", "unselbstständig", "abhängig gemacht"], "ex": ["Wir sind von unserem Auftraggeber abhängig."], "_exampleTrans": {"en": "We are dependent on our client.", "tr": "Müşterimize bağımlıyız.", "ru": "Мы зависим от нашего заказчика.", "uk": "Ми залежимо від нашого замовника.", "es": "Dependemos de nuestro cliente.", "fa": "ما به کارفرمای خود وابسته‌ایم.", "ar": "نحن نعتمد على عميلنا."}}, {"id": "vap_8c22d55632af", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "begeistert + von", "cat": "ap", "syn": ["enthusiastisch", "fasziniert", "hingerissen", "begeistert"], "ex": ["Sie war von den Verkaufszahlen im letzten Quartal begeistert."], "_exampleTrans": {"en": "She was enthusiastic about the sales figures in the last quarter.", "tr": "Son çeyrekteki satış rakamlarından çok etkilenmişti.", "ru": "Она была в восторге от показателей продаж в последнем квартале.", "uk": "Вона була в захваті від показників продажів в останньому кварталі.", "es": "Estaba entusiasmada con las cifras de ventas del último trimestre.", "fa": "او از آمار فروش در سه‌ماههٔ گذشته بسیار هیجان‌زده بود.", "ar": "كانت متحمسة لأرقام المبيعات في الربع الأخير."}}, {"id": "vap_958bfa2724f2", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "entfernt + von", "cat": "ap", "syn": ["weit weg", "abgelegen", "fern", "weit entfernt"], "ex": ["Wir sind von einer guten Bilanz noch meilenweit entfernt."], "_exampleTrans": {"en": "We are still miles away from a good balance sheet.", "tr": "İyi bir bilanço sonucundan hâlâ kilometrelerce uzağız.", "ru": "До хорошего баланса нам ещё очень далеко.", "uk": "До доброго балансу нам ще дуже далеко.", "es": "Todavía estamos muy lejos de un buen balance.", "fa": "ما هنوز از یک ترازنامهٔ خوب بسیار دوریم.", "ar": "ما زلنا بعيدين جدًا عن ميزانية جيدة."}}, {"id": "vap_5c63d32f06ce", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "enttäuscht + von", "cat": "ap", "syn": ["ernüchtert", "enttäuscht", "desillusioniert", "frustriert"], "ex": ["Die GF war von der Entwicklung der Verkaufszahlen enttäuscht."], "_exampleTrans": {"en": "The management was disappointed by the development of the sales figures.", "tr": "Yönetim satış rakamlarının gelişiminden hayal kırıklığına uğradı.", "ru": "Руководство было разочаровано развитием показателей продаж.", "uk": "Керівництво було розчароване розвитком показників продажів.", "es": "La dirección estaba decepcionada por la evolución de las cifras de ventas.", "fa": "مدیریت از روند آمار فروش ناامید شد.", "ar": "شعرت الإدارة بخيبة أمل من تطور أرقام المبيعات."}}, {"id": "vap_c39c4bab5ec1", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "frei + von", "cat": "ap", "syn": ["ungebunden", "unbelastet", "frei", "unabhängig"], "ex": ["Frei von Schulden zu sein, ist das Ziel vieler Unternehmen."], "_exampleTrans": {"en": "Being free of debts is the goal of many companies.", "tr": "Borçsuz olmak birçok şirketin hedefidir.", "ru": "Быть свободным от долгов — цель многих предприятий.", "uk": "Бути вільним від боргів — мета багатьох підприємств.", "es": "Estar libre de deudas es el objetivo de muchas empresas.", "fa": "آزاد بودن از بدهی هدف بسیاری از شرکت‌هاست.", "ar": "أن تكون خاليًا من الديون هو هدف كثير من الشركات."}}, {"id": "vap_dc66060806e7", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "müde + von", "cat": "ap", "syn": ["erschöpft", "abgespannt", "ermüdet", "kraftlos"], "ex": ["Sie war von dem langen Meeting sehr müde."], "_exampleTrans": {"en": "She was very tired from the long meeting.", "tr": "Uzun toplantıdan çok yorgundu.", "ru": "Она очень устала от долгого совещания.", "uk": "Вона дуже втомилася від довгої наради.", "es": "Estaba muy cansada por la larga reunión.", "fa": "او از جلسهٔ طولانی بسیار خسته بود.", "ar": "كانت متعبة جدًا من الاجتماع الطويل."}}, {"id": "vap_12cb9ab3b3fb", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "überzeugt + von", "cat": "ap", "syn": ["sicher", "überzeugt", "gewiss", "überzeugt davon"], "ex": ["Sie sind von der Qualität der neuen Anlage überzeugt."], "_exampleTrans": {"en": "They are convinced of the quality of the new plant.", "tr": "Yeni tesisin kalitesine ikna olmuşlar.", "ru": "Они убеждены в качестве новой установки.", "uk": "Вони переконані в якості нової установки.", "es": "Están convencidos de la calidad de la nueva instalación.", "fa": "آن‌ها به کیفیت تأسیسات جدید اطمینان دارند.", "ar": "إنهم مقتنعون بجودة المنشأة الجديدة."}}, {"id": "vap_104565fb8954", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "unabhängig + von", "cat": "ap", "syn": ["selbstständig", "frei", "autonom", "unabhängig"], "ex": ["Das Projekt wurde unabhängig von den Kostensteigerungen weitergeführt."], "_exampleTrans": {"en": "The project was continued regardless of the cost increases.", "tr": "Proje maliyet artışlarından bağımsız olarak sürdürüldü.", "ru": "Проект был продолжен независимо от роста затрат.", "uk": "Проєкт було продовжено незалежно від зростання витрат.", "es": "El proyecto se continuó independientemente de los aumentos de costes.", "fa": "پروژه بدون توجه به افزایش هزینه‌ها ادامه یافت.", "ar": "استمر المشروع بغض النظر عن زيادات التكاليف."}}, {"id": "vap_a05b5cd5c8fc", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "sicher + vor", "cat": "ap", "syn": ["geschützt", "ungefährdet", "sicher", "abgesichert"], "ex": ["In dieser Abteilung sind alle vor betriebsbedingten Kündigungen sicher."], "_exampleTrans": {"en": "In this department, everyone is safe from dismissals for operational reasons.", "tr": "Bu bölümde herkes işletme gerekçeli işten çıkarmalara karşı güvendedir.", "ru": "В этом отделе все защищены от увольнений по производственным причинам.", "uk": "У цьому відділі всі захищені від звільнень з виробничих причин.", "es": "En este departamento, todos están a salvo de despidos por razones operativas.", "fa": "در این بخش همه از اخراج‌های ناشی از دلایل عملیاتی در امان‌اند.", "ar": "في هذا القسم الجميع في مأمن من الفصل لأسباب تشغيلية."}}, {"id": "vap_e44667cdb65f", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "bereit + zu", "cat": "ap", "syn": ["willig", "vorbereitet", "entschlossen", "verfügbar"], "ex": ["Sie ist zur Übernahme des Geschäftsfeldes bereit."], "_exampleTrans": {"en": "She is ready to take over the business area.", "tr": "İş alanını devralmaya hazır.", "ru": "Она готова к принятию на себя этого направления бизнеса.", "uk": "Вона готова до прийняття цього напряму діяльності.", "es": "Está lista para asumir el área de negocio.", "fa": "او برای به‌عهده گرفتن حوزهٔ کسب‌وکار آماده است.", "ar": "إنها مستعدة لتولي مجال العمل."}}, {"id": "vap_c269ac72256b", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "entschlossen + zu", "cat": "ap", "syn": ["fest entschlossen", "entschieden", "zielstrebig", "resolut"], "ex": ["Sie war zum Kauf der Immobilie entschlossen."], "_exampleTrans": {"en": "She was determined to buy the property.", "tr": "Gayrimenkulü satın almaya kararlıydı.", "ru": "Она была полна решимости купить недвижимость.", "uk": "Вона була рішуче налаштована купити нерухомість.", "es": "Estaba decidida a comprar el inmueble.", "fa": "او برای خرید ملک مصمم بود.", "ar": "كانت مصممة على شراء العقار."}}, {"id": "vap_07ef7afbaaef", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "fähig + zu", "cat": "ap", "syn": ["imstande", "befähigt", "kompetent", "in der Lage"], "ex": ["Dieser Roboter ist zu Pflegeleistungen fähig."], "_exampleTrans": {"en": "This robot is capable of providing care services.", "tr": "Bu robot bakım hizmetleri sunabilecek kapasitededir.", "ru": "Этот робот способен выполнять услуги по уходу.", "uk": "Цей робот здатний виконувати послуги з догляду.", "es": "Este robot es capaz de prestar servicios de cuidado.", "fa": "این ربات قادر به ارائهٔ خدمات مراقبتی است.", "ar": "هذا الروبوت قادر على تقديم خدمات الرعاية."}}, {"id": "vap_1a9db424a288", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "freundlich + zu", "cat": "ap", "syn": ["nett", "höflich", "zuvorkommend", "wohlwollend"], "ex": ["Er ist stets zu allen Menschen sehr freundlich."], "_exampleTrans": {"en": "He is always very friendly to all people.", "tr": "O, tüm insanlara karşı her zaman çok dostçadır.", "ru": "Он всегда очень дружелюбен ко всем людям.", "uk": "Він завжди дуже дружній до всіх людей.", "es": "Él siempre es muy amable con todas las personas.", "fa": "او همیشه با همهٔ مردم بسیار دوستانه رفتار می‌کند.", "ar": "هو دائمًا ودود جدًا مع جميع الناس."}}, {"id": "vap_11b24ce690b4", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "gut + zu/in", "cat": "ap", "syn": ["fähig", "stark", "geeignet", "freundlich"], "ex": ["Er war zu seinen Schülern und Schülerinnen immer sehr gut."], "_exampleTrans": {"en": "He was always very good to his pupils.", "tr": "Öğrencilerine karşı her zaman çok iyiydi.", "ru": "Он всегда был очень добр к своим ученикам и ученицам.", "uk": "Він завжди був дуже добрим до своїх учнів і учениць.", "es": "Siempre fue muy bueno con sus alumnos y alumnas.", "fa": "او همیشه با دانش‌آموزانش بسیار خوب بود.", "ar": "كان دائمًا طيبًا جدًا مع تلاميذه وتلميذاته."}}, {"id": "vap_2abff30c7364", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "höflich + zu", "cat": "ap", "syn": ["zuvorkommend", "manierlich", "respektvoll", "freundlich"], "ex": ["Sie sind zu den Gästen in ihrem Hotel immer sehr höflich."], "_exampleTrans": {"en": "They are always very polite to the guests in their hotel.", "tr": "Otellerindeki misafirlere karşı her zaman çok kibardırlar.", "ru": "Они всегда очень вежливы с гостями в своём отеле.", "uk": "Вони завжди дуже ввічливі з гостями у своєму готелі.", "es": "Siempre son muy corteses con los huéspedes de su hotel.", "fa": "آن‌ها همیشه با مهمانان هتلشان بسیار مؤدب هستند.", "ar": "هم دائمًا مهذبون جدًا مع الضيوف في فندقهم."}}, {"id": "vap_31d597a4fd00", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "lieb + zu", "cat": "ap", "syn": ["nett", "freundlich", "herzlich", "liebevoll"], "ex": ["Seid lieb zu euren Geschwistern!"], "_exampleTrans": {"en": "Be kind to your siblings!", "tr": "Kardeşlerinize iyi davranın!", "ru": "Будьте добры к своим братьям и сёстрам!", "uk": "Будьте добрими до своїх братів і сестер!", "es": "¡Sed buenos con vuestros hermanos!", "fa": "با خواهر و برادرهایتان مهربان باشید!", "ar": "كونوا لطفاء مع إخوتكم وأخواتكم!"}}, {"id": "vap_d2e4f14a81eb", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "nett + zu", "cat": "ap", "syn": ["freundlich", "liebenswürdig", "sympathisch", "angenehm"], "ex": ["Bitte seid nett zueinander!"], "_exampleTrans": {"en": "Please be nice to each other!", "tr": "Lütfen birbirinize iyi davranın!", "ru": "Пожалуйста, будьте добры друг к другу!", "uk": "Будь ласка, будьте добрі одне до одного!", "es": "¡Por favor, sed amables unos con otros!", "fa": "لطفاً با یکدیگر مهربان باشید!", "ar": "من فضلكم كونوا لطفاء مع بعضكم بعضًا!"}}, {"id": "vap_dfb6f5289776", "list": "Verbs and Adjectives with Prepositions", "unit": null, "type": "ap", "word": "unfreundlich + zu", "cat": "ap", "syn": ["kühl", "abweisend", "grob", "unhöflich"], "ex": ["Der Lehrer war zu seinen Schülern und Schülerinnen oft unfreundlich."], "_exampleTrans": {"en": "The teacher was often unfriendly to his pupils.", "tr": "Öğretmen öğrencilerine karşı sık sık kaba davrandı.", "ru": "Учитель часто был недружелюбен к своим ученикам и ученицам.", "uk": "Учитель часто був недружнім до своїх учнів і учениць.", "es": "El profesor fue a menudo poco amable con sus alumnos y alumnas.", "fa": "معلم اغلب با دانش‌آموزانش رفتار غیر دوستانه داشت.", "ar": "كان المعلم غالبًا غير ودود مع تلاميذه وتلميذاته."}}];